# =========================================================================== small parsers
def _k(v: Any) -> str:
    return "" if v is None else str(v).strip().upper()


def _rows(text: str, sep: str) -> list[dict[str, str]]:
    rd = csv.DictReader(io.StringIO(text.lstrip("\ufeff")), delimiter=sep)
    return [{(a or "").strip(): (b or "").strip() for a, b in r.items()} for r in rd]


def _yaml(text: str) -> Any:
    toks = []
    for line in text.split("\n"):
        body = line.strip()
        if body and body[0] != "#":
            toks.append((len(line) - len(line.lstrip()), body))
    pos = [0]

    def val(s: str) -> str:
        s = s.strip()
        return s[1:-1] if len(s) > 1 and s[0] in "'\"" and s[-1] == s[0] else s

    def node(ind: int) -> Any:
        if toks[pos[0]][1][:2] == "- " or toks[pos[0]][1] == "-":
            seq = []
            while pos[0] < len(toks) and toks[pos[0]][0] == ind and toks[pos[0]][1][:1] == "-":
                rest = toks[pos[0]][1][1:].strip()
                if re.match(r"^[\w.]+:( |$)", rest):
                    toks[pos[0]] = (ind + 2, rest)
                    seq.append(node(ind + 2))
                else:
                    pos[0] += 1
                    seq.append(val(rest))
            return seq
        mp = {}
        while pos[0] < len(toks) and toks[pos[0]][0] == ind and toks[pos[0]][1][:2] != "- ":
            key, _, rest = toks[pos[0]][1].partition(":")
            pos[0] += 1
            if rest.strip():
                mp[key.strip()] = val(rest)
            elif pos[0] < len(toks) and (toks[pos[0]][0] > ind or toks[pos[0]][1][:2] == "- "):
                mp[key.strip()] = node(toks[pos[0]][0])
            else:
                mp[key.strip()] = None
        return mp

    return node(toks[0][0]) if toks else {}


_PTOK = re.compile(r"\((?:\\.|[^\\)])*\)|<[0-9A-Fa-f\s]*>|\[|\]|-?\d+(?:\.\d+)?|[A-Za-z]+")


def _pstr(t: str) -> str:
    if t.startswith("<"):
        return bytes.fromhex(re.sub(r"\s", "", t[1:-1])).decode("latin-1")
    return re.sub(r"\\(.)", r"\1", t[1:-1])


def _pdf_lines(path: Path) -> list[list[str]]:
    raw = path.read_bytes()
    lines: list[list[str]] = []
    for m in re.finditer(rb"/Length (\d+) /Filter /FlateDecode >>\nstream\n", raw):
        text = zlib.decompress(raw[m.end():m.end() + int(m.group(1))]).decode("latin-1")
        cells: dict[float, list[tuple[float, str]]] = {}
        for line in text.split("\n"):
            if not (line.startswith("BT ") and line.endswith(" ET")):
                continue
            toks = _PTOK.findall(line[3:-3])
            nums: list[float] = []
            x = y = 0.0
            parts: list[str] = []
            inarr = False
            for t in toks:
                if t == "Tm":
                    x, y = nums[-2], nums[-1]
                elif t == "[":
                    inarr = True
                elif t == "]":
                    inarr = False
                elif t[0] in "(<":
                    parts.append(_pstr(t))
                elif re.fullmatch(r"-?\d+(?:\.\d+)?", t):
                    if not inarr:
                        nums.append(float(t))
            cells.setdefault(y, []).append((x, "".join(parts)))
        for y in sorted(cells, reverse=True):
            lines.append([c.strip() for _, c in sorted(cells[y])])
    return lines


def _pdf(path: Path) -> dict[str, tuple[str, list[dict[str, str]]]]:
    out: dict[str, tuple[str, list]] = {}
    cur = None
    head: dict[str, list[str]] = {}
    for cells in _pdf_lines(path):
        if len(cells) == 1:
            g = re.fullmatch(r"Table ([A-Z]+-\d+)(: .*| \(continued\))", cells[0])
            if g:
                cur = g.group(1)
                if g.group(2).startswith(":"):
                    st = re.search(r"\[(.*)\]$", g.group(2))
                    out[cur] = (st.group(1) if st else "", [])
            continue
        if cur is None or len(cells) < 2:
            continue
        if cur not in head:
            head[cur] = cells
        elif cells != head[cur]:
            out[cur][1].append(dict(zip(head[cur], cells)))
    return out


def _epoch(path: Path) -> date:
    with zipfile.ZipFile(path) as z:
        wb = ET.fromstring(z.read("xl/workbook.xml"))
    pr = wb.find(XNS + "workbookPr")
    flag = "" if pr is None else (pr.get("date1904") or "").strip().lower()
    return date(1904, 1, 1) if flag in ("1", "true") else date(1899, 12, 30)


def _sheet(path: Path, name: str, key: str) -> list[dict[str, str]]:
    z = zipfile.ZipFile(path)
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    rid = [s for s in wb.iter(XNS + "sheet") if s.get("name") == name][0].get(
        "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
    tgt = {r.get("Id"): r.get("Target") for r in ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))}[rid]
    ss = ["".join(x.text or "" for x in si.iter(XNS + "t")) for si in ET.fromstring(z.read("xl/sharedStrings.xml")).iter(XNS + "si")]
    ws = ET.fromstring(z.read("xl/" + tgt.split("xl/")[-1].lstrip("/")))
    z.close()
    grid = []
    for row in ws.iter(XNS + "row"):
        d = {}
        for c in row.iter(XNS + "c"):
            col = re.match(r"[A-Z]+", c.get("r")).group(0)
            if c.get("t") == "inlineStr":
                d[col] = "".join(x.text or "" for x in c.iter(XNS + "t")).strip()
            elif c.find(XNS + "v") is not None:
                v = c.find(XNS + "v").text
                d[col] = (ss[int(v)] if c.get("t") == "s" else v).strip()
        grid.append(d)
    idx = next(i for i, d in enumerate(grid) if d.get("A") == key)
    hdr = grid[idx]
    cols = sorted(hdr, key=lambda c: (len(c), c))
    return [{hdr[c]: d.get(c, "") for c in cols} for d in grid[idx + 1:] if d.get(cols[1], "")]


def _f(s: Any) -> float:
    return float(str(s).strip().replace(",", "."))


def _dil(s: Any) -> int:
    t = _k(s)
    t = t.split(":")[-1].lstrip("X")
    return int(float(t))


