def _shard(path: Path, lay: str) -> list[dict]:  # noqa: C901
    dicts: list[dict] = []
    if lay in ("i_csv", "i_tsv", "i_psv", "i_csvsemi", "i_tsv2", "i_psv2"):
        sep = {"i_csv": ",", "i_tsv": "\t", "i_psv": "|", "i_csvsemi": ";", "i_tsv2": "\t", "i_psv2": "|"}[lay]
        dicts = [{k.replace(" ", "_"): v for k, v in r.items()} for r in _rows(path.read_text(encoding="utf-8"), sep)]
    elif lay in ("i_jsonl", "i_jsonl2"):
        dicts = [json.loads(x) for x in path.read_text(encoding="utf-8").split("\n") if x.strip()]
    elif lay == "i_ndjson":
        for x in path.read_text(encoding="utf-8").split("\n"):
            if x.strip():
                o = json.loads(x)
                dicts.append({"i": o["id"], "r": o["run"], "s": o["order"], "t": o["sample"]["type"], "f": o["sample"]["ref"], "d": o["sample"]["df"],
                              "a": o["areas"]["analyte"], "b": o["areas"]["istd"], "m": o["proc"]["mode"], "v": o["proc"]["rev"], "x": str(o["void"])})
    elif lay == "i_xml":
        for e in ET.parse(path).getroot().findall("inj"):
            ar = {a.get("kind"): a.text for a in e.findall("area")}
            dicts.append({"i": e.get("id"), "r": e.get("run"), "s": e.get("seq"), "t": e.get("type"), "f": e.get("ref"), "d": e.get("df"),
                          "a": ar["analyte"], "b": ar["istd"], "m": e.get("integ"), "v": e.get("rev"), "x": e.get("status")})
    elif lay in ("i_sqlite", "i_db"):
        con = sqlite3.connect(str(path))
        if lay == "i_sqlite":
            q = con.execute("select * from injection")
            cols = [c[0] for c in q.description]
            for row in q:
                o = dict(zip(cols, row))
                dicts.append({"i": o["inj_id"], "r": o["run_token"], "s": o["seq"], "t": o["stype"], "f": o["sref"], "d": o["dil"], "a": o["a_area"],
                              "b": o["is_area"], "m": o["integ"], "v": o["rev"], "x": str(o["voided"])})
        else:
            q = con.execute("select i.id, i.run, i.seq, i.stype, i.sref, i.dil, a.value, b.value, i.integ, i.rev, i.flag from inj i "
                            "join area a on upper(a.inj_id) = upper(i.id) and a.rev = i.rev and a.channel = 'A' "
                            "join area b on upper(b.inj_id) = upper(i.id) and b.rev = i.rev and b.channel = 'IS'")
            for row in q:
                dicts.append(dict(zip("irstfdabmvx", row)))
        con.close()
    elif lay == "i_json":
        ex = json.loads(path.read_text(encoding="utf-8"))["export"]
        dicts = [dict(zip(ex["columns"], r)) for r in ex["rows"]]
    elif lay in ("i_yaml", "i_yml"):
        d = _yaml(path.read_text(encoding="utf-8"))
        dicts = d["injections" if lay == "i_yaml" else "records"]
    elif lay == "i_txt":
        for x in path.read_text(encoding="utf-8").split("\n"):
            if x.strip() and not x.startswith("#"):
                dicts.append({p.split("=", 1)[0].strip(): p.split("=", 1)[1].strip() for p in x.split(";") if "=" in p})
    recs = []
    names = _FIELDS.get(lay, "i r s t f d a b m v x").split()
    for o in dicts:
        vals = []
        for n in names:
            kilo = n.startswith("k:")
            n = n[2:] if kilo else n
            v = o[n]
            vals.append(int(round(_f(v) * 1000)) if kilo else v)
        inj, run, seq, kind, ref, df, a, b, mode, rev, st = vals
        kd = _KIND[_k(kind)]
        r = _k(ref)
        if kd == "STD":
            r = "CS" + re.sub(r"\D", "", r)
        elif kd in ("QC", "DQC"):
            r = {"L": "LQC", "M": "MQC", "H": "HQC", "D": "DQC"}[re.sub(r"^QC-?|QC$", "", r)[:1]] if r not in ("LOW", "MID", "HIGH", "DIL") else \
                {"LOW": "LQC", "MID": "MQC", "HIGH": "HQC", "DIL": "DQC"}[r]
        recs.append({"inj": _k(inj), "run": str(run).strip(), "seq": int(seq), "kind": kd, "ref": r, "df": _dil(df), "a": int(_f(a)), "b": int(_f(b)),
                     "man": _k(mode)[:1] == "M", "rev": int(rev), "void": _k(st) == _LIVE_VOID[lay]})
    return recs


# =========================================================================== numerics
def _sig(q: Fraction, n: int) -> Fraction:
    """Round a rational to n significant digits, half away from zero, exactly."""
    if q == 0:
        return Fraction(0)
    a = abs(q)
    e = len(str(a.numerator // a.denominator)) - 1 if a >= 1 else -len(str(a.denominator // a.numerator))
    while Fraction(10) ** e > a:
        e -= 1
    while Fraction(10) ** (e + 1) <= a:
        e += 1
    scale = Fraction(10) ** (n - 1 - e)
    m = math.floor(a * scale + Fraction(1, 2))
    return (m / scale) * (1 if q > 0 else -1)


def _sigf(x: float, n: int) -> float:
    return float(_sig(Fraction(Decimal(repr(x))), n))


def _dp(q: Fraction, n: int) -> float:
    s = Fraction(10) ** n
    m = math.floor(abs(q) * s + Fraction(1, 2))
    return float(m / s * (1 if q >= 0 else -1))


def _det(m: list[list[Fraction]]) -> Fraction:
    if len(m) == 2:
        return m[0][0] * m[1][1] - m[0][1] * m[1][0]
    return (m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1]) - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
            + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]))


def _fit(x: list[Fraction], y: list[Fraction], wpow: int, p: int) -> list[float]:
    """Exact weighted least squares by Cramer's rule, coefficients rounded to six significant digits."""
    w = [1 / (v ** wpow) for v in x]
    mom = [sum(w[i] * x[i] ** k for i in range(len(x))) for k in range(2 * p - 1)]
    rhs = [sum(w[i] * y[i] * x[i] ** k for i in range(len(x))) for k in range(p)]
    A = [[mom[r + c] for c in range(p)] for r in range(p)]
    d = _det(A)
    coef = []
    for j in range(p):
        Aj = [[rhs[r] if c == j else A[r][c] for c in range(p)] for r in range(p)]
        coef.append(float(_sig(_det(Aj) / d, 6)))
    return coef + ([0.0] if p == 2 else [])


def _back(c: list[float] | None, y: float) -> float | None:
    if c is None:
        return None
    if c[2] == 0.0:
        return (y - c[0]) / c[1]
    q = c[1] ** 2 + 4.0 * c[2] * (y - c[0])
    return None if q < 0 else 2.0 * (y - c[0]) / (c[1] + math.sqrt(q))


def _half_up(v: float) -> float:
    return float(Decimal(repr(v)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def _mins(s: str) -> int:
    sg = -1 if s.strip()[0] == "-" else 1
    h, m = s.strip().lstrip("+-").split(":")
    return sg * (int(h) * 60 + int(m))


def _wall(s: str, base: int, trans: list[tuple[datetime, int]]) -> datetime:
    w = datetime.strptime(s.strip()[:16].replace("T", " "), "%Y-%m-%d %H:%M")
    offs = sorted({base} | {o for _, o in trans})

    def off_at(u: datetime) -> int:
        cur = base
        for when, o in trans:
            if u >= when:
                cur = o
        return cur

    best = None
    for off in offs:
        u = (w - timedelta(minutes=off)).replace(tzinfo=Z)
        if off_at(u) == off and (best is None or u < best):
            best = u
    if best is not None:
        return best
    prev = base
    for when, o in trans:
        before, after = (w - timedelta(minutes=prev)).replace(tzinfo=Z), (w - timedelta(minutes=o)).replace(tzinfo=Z)
        if before >= when > after:
            return before
        prev = o
    raise ValueError("wall time outside the calendar")


def _inst(s: str, base: int, trans: list) -> datetime:
    s = s.strip()
    if s.endswith("Z") or re.search(r"[+-]\d\d:\d\d$", s):
        return datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(Z)
    return _wall(s, base, trans)


def _hours(a: datetime, b: datetime) -> float:
    return _dp(Fraction(int((a - b).total_seconds()), 3600), 4)


def _median(v: list[float]) -> float:
    v = sorted(v)
    n = len(v)
    return v[n // 2] if n % 2 else (v[n // 2 - 1] + v[n // 2]) / 2


# =========================================================================== derivation
def _state(root: Path, flip: str = "") -> dict[str, Any]:  # noqa: C901
    P = _yaml((root / "analysis_profile_be.yml").read_text(encoding="utf-8"))
    study = _k(P["study_id"])
    AN = [_k(a) for a in P["analytes"]]
    PIV = [_k(a) for a in P["pivotal_analytes"]]
    PRM = list(P["parameters"])
    SCOPE = {_k(s) for s in P["subjects_in_scope"]}
    memo = _pdf(root / "ba_stat_governance_memo.pdf")
    meth = {_k(r["analyte"]): r for r in memo["M-2"][1]}
    okC1 = {_k(r["code"]) for r in memo["C-1"][1] if _k(r["allowed"]) == "Y"}
    okC2 = {_k(r["code"]) for r in memo["C-2"][1] if _k(r["allowed"]) == "Y"}
    eme = {_k(r["preferred_term"]) for r in memo["E-1"][1] if _k(r["counts_as_emesis"]) == "Y"}
    tt = {int(r["df"]): r for r in memo["T-1"][1]}
    rul = [r for r in memo["R-1"][1] if _k(r["study"]) == study]
    live = [r for r in rul if _k(r["status"]) == "IN FORCE"]
    calv = _yaml((root / "site_calendar.yml").read_text(encoding="utf-8"))
    base = _mins(calv["base_offset"])
    trans = sorted((datetime.fromisoformat(t["at_utc"].replace("Z", "+00:00")), _mins(t["offset_after"])) for t in calv["transitions"])
    wb = root / "bioanalytical_workbook_v3.xlsx"
    ep = _epoch(wb)
    RUN = {}
    for r in _sheet(wb, "RunPlan", "run_id"):
        if _k(r["study"]) == study:
            RUN[_k(r["run_id"])] = (_k(r["analyte"]), _k(r["run_type"]), _k(r["cal_lot"]), _k(r["qc_lot"]), ep + timedelta(days=int(_f(r["analysis_date"]))))
    NOM = {(_k(r["lot"]), _k(r["level"])): r["certified"].strip() for r in _sheet(wb, P["nominal_sheet"], "lot")}
    QNOM = {(_k(r["lot"]), _k(r["level"])): _f(r["certified"]) for r in _sheet(wb, "QCLots", "lot")}
    SEQ = {_k(r["subject"]): _k(r["sequence"]) for r in _sheet(wb, "Randomization", "subject")}
    con = sqlite3.connect(str(root / "entity_alias_register.sqlite"))
    RA = {_k(a): _k(b) for a, b in con.execute("select token, run_id from run_alias")}
    raw_sa = {_k(a): _k(b) for a, b, c in con.execute("select token, subject_id, study from subject_alias") if _k(c) == study}
    con.close()
    RA.update({r: r for r in RUN})
    SA: dict[str, str] = {}
    for tok in raw_sa:
        cur, seen = tok, set()
        while cur not in SEQ and cur in raw_sa and cur not in seen:
            seen.add(cur)
            cur = raw_sa[cur]
            if flip == "one_hop_alias":
                break
        if cur in SEQ:
            SA[tok] = cur
    SA.update({s: s for s in SEQ})
    REL = {}
    for e in ET.parse(root / "tube_relabel_journal.xml").getroot().findall("relabel"):
        if _k(e.get("status")) == "ACTIVE" and (e.get("study") is None or _k(e.get("study")) == study):
            REL[_k(e.get("new"))] = _k(e.get("old"))
    TUBE = {}
    for r in _rows((root / "tube_manifest_main.csv").read_text(encoding="utf-8"), ","):
        n = _k(r["nominal_h"])
        TUBE[_k(r["tube_id"])] = [SA.get(_k(r["subject"])), int(r["period"]), 0.0 if n == "PRE" else (None if n == "UNS" else _f(n)),
                                  _k(r["status"]).replace(" ", "_") == "COLLECTED", r["subject"]]
    for r in _yaml((root / "tube_manifest_addendum.yaml").read_text(encoding="utf-8"))["tubes"]:
        n = _k(r["nominal_h"])
        TUBE[_k(r["tube"])] = [SA.get(_k(r["subject"])), int(r["period"]), 0.0 if n == "PRE" else (None if n == "UNS" else _f(n)),
                               _k(r["status"]).replace(" ", "_") == "COLLECTED", r["subject"]]
    stoks = [v[4] for v in TUBE.values()]
    DOSE = {}
    for r in _rows((root / "dose_admin_p1.csv").read_text(encoding="utf-8"), ","):
        stoks.append(r["subject"])
        if _k(r["event"]) == "DOSE":
            DOSE[(SA.get(_k(r["subject"])), int(r["period"]))] = _wall(r["local_time"], base, trans)
    x2 = ET.parse(root / "dose_admin_p2.xml").getroot()
    for e in x2.findall("event"):
        stoks.append(e.get("subject"))
        if _k(e.get("type")) == "DOSE":
            DOSE[(SA.get(_k(e.get("subject"))), int(x2.get("period")))] = _inst(e.get("at"), base, trans)
    DRAW: dict[str, Any] = {}
    for r in _rows((root / "draw_times_g1.tsv").read_text(encoding="utf-8"), "\t"):
        stoks.append(r["subject"])
        DRAW[_k(r["tube"])] = r["drawn_local"] or None
    for x in (root / "draw_times_g2.jsonl").read_text(encoding="utf-8").split("\n"):
        if x.strip():
            o = json.loads(x)
            stoks.append(o["subj"])
            DRAW[_k(o["tube"])] = o["drawn_at"] or None
    cj = [json.loads(x) for x in (root / "draw_time_corrections.ndjson").read_text(encoding="utf-8").split("\n") if x.strip()]
    cnt = {int(o["seq"]): o for o in cj if _k(o["status"]) == "POSTED" and str(o["field"]).strip() == "drawn_local"}
    act = (lambda o: _k(o.get("action")) or "SET")
    live_c: dict[int, bool] = {}
    for sq in sorted(cnt, reverse=True):
        live_c[sq] = not any(live_c.get(r2) and act(cnt[r2]) == "REVERSE" and int(cnt[r2]["reverses"]) == sq for r2 in cnt if r2 > sq)
    if flip == "ignore_reversals":
        live_c = {sq: True for sq in cnt}
    top: dict[str, int] = {}
    for sq, o in cnt.items():
        if live_c[sq] and act(o) == "SET":
            t = _k(o["tube"])
            if t not in top or sq > top[t]:
                top[t] = sq
    for t, sq in top.items():
        DRAW[t] = cnt[sq]["value"] or None
    DRAWU = {t: (None if v is None else _inst(v, base, trans)) for t, v in DRAW.items()}
    con = sqlite3.connect(str(root / "ae_listing.db"))
    AE = []
    for st, sj, pe, pt, on in con.execute("select study, subject, period, pt, onset_local from ae_events"):
        if _k(st) == study:
            stoks.append(sj)
            AE.append((SA.get(_k(sj)), int(pe), _k(pt), _wall(on, base, trans)))
    con.close()
    WD = set()
    for r in _rows((root / "subject_disposition.psv").read_text(encoding="utf-8"), "|"):
        stoks.append(r["subject"])
        if _k(r["event"]) == "WITHDRAWN":
            WD.add(SA.get(_k(r["subject"])))
    stoks += [r["target"] for r in rul if _k(r["action"]) == "EXCLUDE_SUBJECT"]
    con = sqlite3.connect(str(root / "integration_audit_trail.db"))
    lastA: dict = {}
    for ref, rv, code, st, ts in con.execute("select injection_ref, revision, reason_code, status, ts from audit_entry order by ts"):
        lastA[(_k(ref), int(rv))] = (_k(st), _k(code))
    con.close()
    APP = {k for k, (st, code) in lastA.items() if st == "APPROVED" and code in okC1}
    REQ = [json.loads(x) for x in (root / "std_exclusion_requests.jsonl").read_text(encoding="utf-8").split("\n") if x.strip()]
    LOG = _rows((root / "reassay_request_log.csv").read_text(encoding="utf-8"), ",")
    DASH = {_k(r["run_id"]): _k(r["lab_status"]) for r in _rows((root / "run_status_dashboard.csv").read_text(encoding="utf-8"), ",")}
    PUB = _rows((root / "be_report_published.csv").read_text(encoding="utf-8"), ",")
    PUBS = json.loads((root / "be_statistics_published.json").read_text(encoding="utf-8"))
    CAT = json.loads((root / "ingest_catalog_be.json").read_text(encoding="utf-8"))["shards"]
    SH = [(c, _shard(root / c["file"], c["layout"])) for c in CAT if c.get("active") is True]

    # ----------------------------------------------------------------- revisions
    nread = sum(len(r) for _, r in SH)
    uniq: dict[tuple, dict] = {}
    for _, recs in SH:
        for r in recs:
            uniq.setdefault((r["inj"], r["rev"]), r)
    groups: dict[str, list] = {}
    for r in uniq.values():
        groups.setdefault(r["inj"], []).append(r)
    EFF, inadm, sup, nvoid = {}, 0, 0, 0
    for inj, g in groups.items():
        ok = [r for r in g if r["void"] or not r["man"] or (inj, r["rev"]) in APP]
        inadm += len(g) - len(ok)
        if not ok:
            continue
        sup += len(ok) - 1
        top_r = sorted(ok, key=lambda r: -r["rev"])[0]
        if top_r["void"]:
            nvoid += 1
        else:
            EFF[inj] = top_r
    tube = (lambda ref: (lambda t: t if t in TUBE else None)(REL.get(ref, ref)))
    DED = {"rows_read": nread, "duplicate_copies": nread - len(uniq), "superseded": sup, "inadmissible_manual": inadm, "voided": nvoid,
           "effective_injections": len(EFF),
           "standards": sum(r["kind"] == "STD" for r in EFF.values()), "qcs": sum(r["kind"] in ("QC", "DQC") for r in EFF.values()),
           "blank_zero": sum(r["kind"] in ("BLANK", "ZERO") for r in EFF.values()),
           "study_sample_injections": sum(r["kind"] == "UNK" and tube(r["ref"]) is not None for r in EFF.values()),
           "foreign_injections": sum(r["kind"] == "UNK" and tube(r["ref"]) is None for r in EFF.values())}

    # ----------------------------------------------------------------- runs
    byrun: dict[str, list] = {}
    for r in EFF.values():
        rid = RA.get(_k(r["run"]))
        if rid in RUN:
            byrun.setdefault(rid, []).append(r)
    AC = {}
    for q in REQ:
        if _k(q.get("status")) == "APPROVED" and _k(q.get("code")) in okC2:
            AC.setdefault(RA.get(_k(q.get("run"))), set()).add(_k(q.get("injection")))
    rejected = {RA.get(_k(r["target"])) for r in live if _k(r["action"]) == "REJECT_RUN"}
    FIT = {}
    for rid in sorted(RUN):
        an, rtype, cl, ql, rdate = RUN[rid]
        if an not in AN:
            continue
        M = meth[an]
        quad = M["model"].strip() == "quadratic"
        p = 3 if quad else 2
        wpow = 2 if M["weighting"].strip() == "1/x^2" else 1
        L15, L20 = float(M["std_limit_pct"]), float(M["lloq_std_limit_pct"])
        inj = sorted(byrun.get(rid, []), key=lambda r: r["seq"])
        std = [dict(r, nomq=Fraction(NOM[(cl, r["ref"])]), nom=float(NOM[(cl, r["ref"])]), y=r["a"] / r["b"], yq=Fraction(r["a"], r["b"]))
               for r in inj if r["kind"] == "STD"]
        ac = {s["inj"] for s in std if s["inj"] in AC.get(rid, set())}
        keep = [s for s in std if s["inj"] not in ac]
        coef, rem, nfit = None, [], 0
        lim = (lambda s: L20 if s["ref"] == "CS1" else L15)
        if len(keep) > p:
            while True:
                coef = _fit([s["nomq"] for s in keep], [s["yq"] for s in keep], wpow, p)
                nfit += 1
                bad = []
                for s in keep:
                    v = _back(coef, s["y"])
                    sc = float("inf") if v is None else abs(v - s["nom"]) / s["nom"] * 100 / lim(s)
                    if sc > 1:
                        bad.append((sc, s["nom"], s["seq"], s))
                if not bad or len(keep) <= p + 1:
                    break
                worst = max(bad, key=lambda b: b[:3])[3]
                keep = [s for s in keep if s is not worst]
                rem.append(worst["inj"])
        stl = False
        for s in std:
            s["rd"] = _back(coef, s["y"])
            s["dv"] = None if s["rd"] is None else (s["rd"] - s["nom"]) / s["nom"] * 100
            s["st"] = "NO_CURVE" if coef is None else "ASSIGNABLE" if s["inj"] in ac else "REMOVED" if s["inj"] in rem else "RETAINED"
            if s["st"] == "RETAINED" and (s["dv"] is None or abs(s["dv"]) > lim(s)):
                stl = True
        kept = [s for s in std if s["st"] == "RETAINED"]
        qcs = []
        for r in inj:
            if r["kind"] in ("QC", "DQC"):
                rd = _back(coef, r["a"] / r["b"])
                nm = QNOM[(ql, r["ref"])]
                bk = None if rd is None else rd * r["df"]
                dv = None if bk is None else (bk - nm) / nm * 100
                L = float(M["dqc_limit_pct" if r["kind"] == "DQC" else "qc_limit_pct"])
                qcs.append(dict(r, nom=nm, bk=bk, dv=dv, ok=dv is not None and abs(dv) <= L))
        reg = [q for q in qcs if q["kind"] == "QC"]
        npass = sum(1 for q in reg if q["ok"])
        lv = {s["ref"] for s in kept}
        mf = [int(v) for v in M["min_std_fraction"].split("/")]
        qf = [int(v) for v in M["min_qc_fraction"].split("/")]
        lf = [int(v) for v in M["min_qc_level_fraction"].split("/")]
        why = ("RULING" if rid in rejected else "NO_CURVE" if coef is None else "STD_LIMIT" if stl else
               "STD_COUNT" if len(kept) * mf[1] < len(std) * mf[0] else "STD_LEVELS" if len(lv) < int(M["min_levels"]) else
               "QC_TOTAL" if reg and npass * qf[1] < len(reg) * qf[0] else "")
        if not why:
            for L_ in sorted({q["ref"] for q in reg}):
                g = [q for q in reg if q["ref"] == L_]
                if sum(q["ok"] for q in g) * lf[1] < len(g) * lf[0]:
                    why = "QC_LEVEL"
                    break
        dils = any(r["kind"] == "UNK" and r["df"] > 1 for r in inj)
        dq = [q for q in qcs if q["kind"] == "DQC"]
        FIT[rid] = {"an": an, "type": rtype, "cl": cl, "date": rdate, "coef": coef, "p": p, "std": std, "qcs": qcs, "rem": rem, "nfit": nfit, "ac": ac,
                    "lo": min((s["nom"] for s in kept), default=None), "hi": max((s["nom"] for s in kept), default=None),
                    "acc": not why, "why": why, "dqc": ("PASS" if len(dq) > 1 and all(q["ok"] for q in dq) else "FAIL") if dils else "NA",
                    "nlev": len(lv), "npass": npass, "nreg": len(reg), "inj": inj, "model": M["model"].strip(), "wt": M["weighting"].strip()}

    # ----------------------------------------------------------------- results
    rlog = {}
    for r in LOG:
        if _k(r["status"]) != "CANCELLED":
            key = (REL.get(_k(r["tube"]), _k(r["tube"])), _k(r["analyte"]), RA.get(_k(r["run"])))
            rlog.setdefault(key, re.sub(r"[ -]", "_", _k(r["reason"])))
    conc = (lambda v: v) if flip == "unrounded_conc" else (lambda v: _sigf(v, 4))
    RES: dict[tuple, list] = {}
    for rid, F in FIT.items():
        for r in F["inj"]:
            if r["kind"] != "UNK":
                continue
            t = tube(r["ref"])
            if t is None or TUBE[t][0] not in SCOPE:
                continue
            why = "ISR" if F["type"] == "ISR" else rlog.get((t, F["an"], rid), "ORIGINAL")
            y = r["a"] / r["b"]
            rd = _back(F["coef"], y)
            fl = ("RUN_REJECTED" if not F["acc"] else "DQC_FAIL" if r["df"] > 1 and F["dqc"] == "FAIL" else
                  "ALQ" if rd is None else "BLQ" if rd < F["lo"] else "ALQ" if rd > F["hi"] else "OK")
            RES.setdefault((t, F["an"]), []).append({"run": rid, "inj": r["inj"], "seq": r["seq"], "why": why, "df": r["df"], "y": y, "rd": rd,
                                                     "c": conc(rd * r["df"]) if fl == "OK" else None, "fl": fl, "use": False, "ord": (F["date"], rid, r["seq"])})
    xt = {REL.get(_k(r["target"]), _k(r["target"])) for r in live if _k(r["action"]) == "EXCLUDE_SAMPLE"}
    REP = {}
    for t, tb in TUBE.items():
        if tb[0] not in SCOPE:
            continue
        for an in AN:
            L = sorted(RES.get((t, an), []), key=lambda x: x["ord"])
            if t in xt:
                REP[(t, an)] = ("EXCL", "RULING", None, "")
                continue
            if not tb[3]:
                REP[(t, an)] = ("NOT_COLLECTED", "NONE", None, "")
                continue
            cand = [x for x in L if x["fl"] in ("OK", "BLQ", "ALQ") and x["why"] != "ISR"]
            bs = [x for x in cand if x["why"] in ("ORIGINAL", "RUN_FAIL")]
            if not bs:
                REP[(t, an)] = ("NR", "NONE", None, "")
                continue
            b0 = bs[0]
            if b0["fl"] == "ALQ":
                dl = [x for x in cand if x["why"] == "ALQ" and x["fl"] == "OK"]
                if dl:
                    dl[0]["use"] = True
                    REP[(t, an)] = ("OK", "ALQ_DILUTION", dl[0]["c"], dl[0]["run"])
                else:
                    REP[(t, an)] = ("NR", "ALQ_NO_DILUTION", None, b0["run"])
                continue
            b0["use"] = True
            if b0["fl"] == "BLQ":
                REP[(t, an)] = ("BLQ", b0["why"], None, b0["run"])
                continue
            pk = [x for x in cand if x["why"] == "PK_REPEAT" and x["fl"] in ("OK", "BLQ")][:2]
            if len(pk) == 2:
                for x in pk:
                    x["use"] = True
                v = sorted([b0["c"]] + [x["c"] if x["fl"] == "OK" else 0.0 for x in pk])[1]
                REP[(t, an)] = ("OK", "PK_REPEAT_MEDIAN", v, b0["run"]) if v > 0 else ("BLQ", "PK_REPEAT_MEDIAN", None, b0["run"])
            else:
                REP[(t, an)] = ("OK", b0["why"], b0["c"], b0["run"])

    # ----------------------------------------------------------------- times and NCA
    EL = {}
    for t, tb in TUBE.items():
        d, u = DOSE.get((tb[0], tb[1])), DRAWU.get(t)
        EL[t] = 0.0 if tb[2] == 0 else (_hours(u, d) if tb[3] and d is not None and u is not None else None)
    minp, tol, xl = int(P["lambda_z_min_points"]), float(P["lambda_z_adj_r2_tolerance"]), float(P["extrap_limit_pct"])
    NCA = {}
    for s in sorted(SEQ):
        if s not in SCOPE:
            continue
        for per in (1, 2):
            if (s, per) not in DOSE:
                continue
            for an in AN:
                obs = sorted((EL[t], tb[2], REP[(t, an)]) for t, tb in TUBE.items()
                             if tb[0] == s and tb[1] == per and tb[2] is not None and EL[t] is not None and REP[(t, an)][0] in ("OK", "BLQ"))
                pts, first = [], False
                for e, _, rp in obs:
                    if rp[0] == "OK":
                        first = True
                        pts.append((e, rp[2]))
                    elif not first:
                        pts.append((e, 0.0))
                R: dict[str, Any] = {"np": len(pts), "flag": "NOT_EVALUABLE", "cand": [], "n": None}
                if sum(1 for _, c in pts if c > 0) >= 3:
                    cm = max(c for _, c in pts)
                    im = [c for _, c in pts].index(cm)
                    il = max(i for i, (_, c) in enumerate(pts) if c > 0)
                    auc = 0.0
                    for i in range(il):
                        (t1, c1), (t2, c2) = pts[i], pts[i + 1]
                        auc += (t2 - t1) * ((c1 - c2) / math.log(c1 / c2) if 0 < c2 < c1 else (c1 + c2) / 2)
                    R.update(cmax=cm, tmax=pts[im][0], clast=pts[il][1], tlast=pts[il][0], auc=auc, flag="NO_LAMBDA_Z", pts=pts[:il + 1])
                    tail = [(t_, math.log(c)) for i, (t_, c) in enumerate(pts) if i > im and c > 0]
                    for n in range(minp, len(tail) + 1):
                        seg = tail[-n:]
                        st_ = sum(a for a, _ in seg)
                        sy = sum(b for _, b in seg)
                        stt = sum(a * a for a, _ in seg)
                        sty = sum(a * b for a, b in seg)
                        slope = (n * sty - st_ * sy) / (n * stt - st_ * st_)
                        icpt = (sy - slope * st_) / n
                        ss_r = sum((b - icpt - slope * a) ** 2 for a, b in seg)
                        ss_t = sum((b - sy / n) ** 2 for _, b in seg)
                        rr = 1.0 - (ss_r / ss_t if ss_t > 0 else 0.0)
                        R["cand"].append({"n": n, "slope": slope, "intercept": icpt, "adj_r2": 1 - (1 - rr) * (n - 1) / (n - 2), "eligible": slope < 0})
                    el = [c for c in R["cand"] if c["eligible"]]
                    if el:
                        best = max(c["adj_r2"] for c in el)
                        ch = [c for c in el if c["adj_r2"] >= best - tol][-1]
                        lz = -ch["slope"]
                        cp = math.exp(ch["intercept"] - lz * R["tlast"])
                        ai = auc + cp / lz
                        R.update(n=ch["n"], lz=lz, adj=ch["adj_r2"], hl=math.log(2) / lz, cp=cp, ai=ai, ex=cp / lz / ai * 100,
                                 flag="EXTRAP_GT_LIMIT" if cp / lz / ai * 100 > xl else "OK")
                NCA[(s, per, an)] = R
    xs = {SA.get(_k(r["target"])) for r in live if _k(r["action"]) == "EXCLUDE_SUBJECT"}
    return {"P": P, "study": study, "AN": AN, "PIV": PIV, "PRM": PRM, "SCOPE": SCOPE, "meth": meth, "eme": eme, "tt": tt, "rul": rul, "live": live,
            "RUN": RUN, "SEQ": SEQ, "RA": RA, "SA": SA, "REL": REL, "TUBE": TUBE, "DOSE": DOSE, "DRAWU": DRAWU, "AE": AE, "WD": WD, "DASH": DASH,
            "PUB": PUB, "PUBS": PUBS, "CAT": CAT, "SH": SH, "EFF": EFF, "DED": DED, "FIT": FIT, "RES": RES, "REP": REP, "EL": EL, "NCA": NCA,
            "REQ": REQ, "LOG": LOG, "stoks": stoks, "xs": xs, "flip": flip}


def _candidates(S: dict[str, Any]) -> list[str]:
    return [s for s in sorted(S["SEQ"]) if s in S["SCOPE"] and s not in S["xs"] and s not in S["WD"]
            and (s, 1) in S["DOSE"] and (s, 2) in S["DOSE"]]


def _ref_tmax(S: dict[str, Any]) -> dict[str, float]:
    piv = S["PIV"][0]
    out = {}
    for s in _candidates(S):
        per = 1 if S["SEQ"][s][0] == "R" else 2
        R = S["NCA"].get((s, per, piv))
        if R is not None and R["flag"] != "NOT_EVALUABLE":
            out[s] = R["tmax"]
    return out


def _emetic(S: dict[str, Any], cands: list[str], win: float) -> dict[str, tuple[int, float]]:
    em: dict[str, tuple[int, float]] = {}
    for subj, per, pt, on in sorted(S["AE"], key=lambda e: (e[1], e[3])):
        d = S["DOSE"].get((subj, per))
        if subj in cands and pt in S["eme"] and d is not None and subj not in em:
            h = _hours(on, d)
            if 0 <= h <= win:
                em[subj] = (per, h)
    return em


def _emesis_passes(S: dict[str, Any]) -> None:
    cands = _candidates(S)
    tmax = _ref_tmax(S)
    fac = float(S["P"]["emesis_window_factor"])
    passes: list[tuple[float, float, dict]] = []
    prev: set = set()
    while True:
        vals = [v for s, v in tmax.items() if s not in prev]
        med = sum(vals) / len(vals)
        win = fac * med
        em = _emetic(S, cands, win)
        cur = set(em)
        hit = [j for j, (_, _, e) in enumerate(passes) if set(e) == cur]
        passes.append((med, win, em))
        if S["flip"] == "single_pass_emesis":
            S["em_pass"], S["em_settle"] = 0, "CONVERGED"
            break
        if hit:
            j = hit[0]
            k = len(passes) - 1
            if j == k - 1:
                S["em_pass"], S["em_settle"] = k, "CONVERGED"
            else:
                S["em_pass"] = max(range(j, k), key=lambda i: (passes[i][1], -i))
                S["em_settle"] = "CYCLE"
            break
        prev = cur
    S["passes"] = passes
    med, win, em = passes[S["em_pass"]]
    S["med"], S["win"], S["em"] = med, win, em


def _emesis_inputs(root: Path) -> dict[str, Any]:
    S = _state(root)
    return {"factor": float(S["P"]["emesis_window_factor"]), "tmax": _ref_tmax(S), "base": set(_candidates(S))}


def _stats(S: dict[str, Any]) -> None:  # noqa: C901
    P, AN, NCA, SEQ = S["P"], S["AN"], S["NCA"], S["SEQ"]
    _emesis_passes(S)
    em = S["em"]
    xs = S["xs"]
    pre = {(tb[0], tb[1]): t for t, tb in S["TUBE"].items() if tb[2] == 0}
    cl = float(P["carryover_limit_pct"])
    POP, EX = {}, []
    for s in sorted(SEQ):
        for an in AN:
            R1, R2 = NCA.get((s, 1, an)), NCA.get((s, 2, an))
            why, per, val = "", None, None
            if s not in S["SCOPE"]:
                why = "NOT_IN_SCOPE"
            elif s in xs:
                why = "RULING"
            elif s in S["WD"]:
                why = "WITHDRAWN"
            elif (s, 1) not in S["DOSE"] or (s, 2) not in S["DOSE"]:
                why, per = "INCOMPLETE", (1 if (s, 1) not in S["DOSE"] else 2)
            elif s in em:
                why, (per, val) = "EMESIS", em[s]
            elif R1["flag"] == "NOT_EVALUABLE" or R2["flag"] == "NOT_EVALUABLE":
                why, per = "NOT_EVALUABLE", (1 if R1["flag"] == "NOT_EVALUABLE" else 2)
            else:
                for k, R in ((1, R1), (2, R2)):
                    rp = S["REP"].get((pre.get((s, k)), an))
                    if rp and rp[0] == "OK" and rp[2] > cl / 100 * R["cmax"]:
                        why, per, val = "CARRYOVER", k, rp[2] / R["cmax"] * 100
                        break
            if why and why != "NOT_IN_SCOPE":
                EX.append({"subject_id": s, "analyte": an, "reason": why, "period": per, "value": val})
            for prm in ("Cmax", "AUClast", "AUCinf"):
                w = why
                if not w and prm == "AUCinf":
                    fl = {R1["flag"], R2["flag"]}
                    w = "PARAM_NA" if "NO_LAMBDA_Z" in fl else "EXTRAP" if "EXTRAP_GT_LIMIT" in fl else ""
                POP[(s, an, prm)] = w
    S["POP"], S["EX"] = POP, EX
    alpha = float(P["alpha"])
    col = [c for c in next(iter(S["tt"].values())) if c.startswith("p=") and abs(float(c[2:]) - (1 - alpha)) < 1e-9][0]
    lo, hi = float(P["be_lower_pct"]), float(P["be_upper_pct"])
    key = {"Cmax": "cmax", "AUClast": "auc", "AUCinf": "ai"}
    BE = {}
    for an in AN:
        role = "PIVOTAL" if an in S["PIV"] else "SUPPORTIVE"
        pr = {}
        for prm in S["PRM"]:
            g = {"TR": [], "RT": []}
            for s in sorted(SEQ):
                if not POP[(s, an, prm)]:
                    g[SEQ[s]].append((math.log(NCA[(s, 1, an)][key[prm]]), math.log(NCA[(s, 2, an)][key[prm]])))
            a, b = g["TR"], g["RT"]
            n1, n2 = len(a), len(b)
            if n1 < 1 or n2 < 1 or n1 + n2 - 2 < 1:
                pr[prm] = {k: None for k in ("df", "t_quantile", "estimate_log", "se_log", "mse", "cv_intra_pct", "lsmean_T", "lsmean_R", "ratio_pct",
                                             "ci_lower_pct", "ci_upper_pct", "ratio_pct_r", "ci_lower_r", "ci_upper_r")}
                pr[prm].update(n_TR=n1, n_RT=n2, result="NOT_ESTIMABLE")
                continue
            da = [(y2 - y1) / 2 for y1, y2 in a]
            db = [(y2 - y1) / 2 for y1, y2 in b]
            ma, mb = sum(da) / n1, sum(db) / n2
            df = n1 + n2 - 2
            s2 = (sum((v - ma) ** 2 for v in da) + sum((v - mb) ** 2 for v in db)) / df
            se = math.sqrt(s2 / n1 + s2 / n2)
            est = mb - ma
            tq = _f(S["tt"][df][col])
            lt = 0.5 * (sum(y1 for y1, _ in a) / n1 + sum(y2 for _, y2 in b) / n2)
            lr = 0.5 * (sum(y2 for _, y2 in a) / n1 + sum(y1 for y1, _ in b) / n2)
            rt, l_, u_ = math.exp(est) * 100, math.exp(est - tq * se) * 100, math.exp(est + tq * se) * 100
            res = "INFO" if role != "PIVOTAL" else ("PASS" if _half_up(l_) >= lo and _half_up(u_) <= hi else "FAIL")
            pr[prm] = {"n_TR": n1, "n_RT": n2, "df": df, "t_quantile": tq, "estimate_log": est, "se_log": se, "mse": 2 * s2,
                       "cv_intra_pct": math.sqrt(math.expm1(2 * s2)) * 100, "lsmean_T": math.exp(lt), "lsmean_R": math.exp(lr), "ratio_pct": rt,
                       "ci_lower_pct": l_, "ci_upper_pct": u_, "ratio_pct_r": _half_up(rt), "ci_lower_r": _half_up(l_), "ci_upper_r": _half_up(u_), "result": res}
        con = ("BIOEQUIVALENT" if all(v["result"] == "PASS" for v in pr.values()) else "NOT_BIOEQUIVALENT") if role == "PIVOTAL" else "SUPPORTIVE"
        BE[an] = {"role": role, "conclusion": con, "parameters": pr}
    S["BE"] = {"study_id": S["P"]["study_id"], "alpha": alpha, "ci_level_pct": 100 * (1 - 2 * alpha), "limits_pct": [lo, hi], "analytes": BE}
    S["col"] = col


def _tab(h: list[str], rows: list[list[Any]], sep: str) -> str:
    def c(v: Any) -> str:
        return "" if v is None else repr(v) if isinstance(v, float) else str(v)
    return sep.join(h) + "\n" + "".join(sep.join(c(v) for v in r) + "\n" for r in rows)


def _render(S: dict[str, Any]) -> dict[str, str]:  # noqa: C901
    O: dict[str, str] = {}
    AN, FIT, RES, REP, NCA, SEQ = S["AN"], S["FIT"], S["RES"], S["REP"], S["NCA"], S["SEQ"]
    aix = {a: i for i, a in enumerate(AN)}
    runs = [{"run_id": r, "analyte": F["an"], "model": F["model"], "weighting": F["wt"], "cal_lot": F["cl"],
             "coefficients": None if F["coef"] is None else {"a": F["coef"][0], "b": F["coef"][1], "c": F["coef"][2] if F["p"] == 3 else None},
             "n_standards": len(F["std"]), "n_assignable": len(F["ac"]), "n_retained": sum(s["st"] == "RETAINED" for s in F["std"]), "removed": F["rem"],
             "iterations": F["nfit"], "lloq": F["lo"], "uloq": F["hi"]} for r, F in sorted(FIT.items())]
    O["calibration_fits.json"] = json.dumps({"study_id": S["P"]["study_id"], "nominal_sheet": S["P"]["nominal_sheet"], "runs": runs})
    O["standard_backcalc.tsv"] = _tab(["run_id", "injection_id", "level", "nominal", "response", "back_calculated", "deviation_pct", "status"],
                                      [[r, s["inj"], s["ref"], s["nom"], s["y"], s["rd"], s["dv"], s["st"]] for r, F in sorted(FIT.items()) for s in F["std"]], "\t")
    O["qc_results.csv"] = _tab(["run_id", "injection_id", "qc_level", "nominal", "dilution_factor", "back_calculated", "deviation_pct", "pass"],
                               [[r, q["inj"], q["ref"], q["nom"], q["df"], q["bk"], q["dv"], "Y" if q["ok"] else "N"] for r, F in sorted(FIT.items()) for q in F["qcs"]], ",")
    O["run_acceptance.csv"] = _tab(["run_id", "analyte", "run_type", "analysis_date", "n_std_total", "n_std_retained", "n_levels_retained", "qc_total", "qc_pass",
                                    "status", "reason", "dqc_status", "lab_status", "agrees"],
                                   [[r, F["an"], F["type"], F["date"].isoformat(), len(F["std"]), sum(s["st"] == "RETAINED" for s in F["std"]), F["nlev"], F["nreg"],
                                     F["npass"], "ACCEPTED" if F["acc"] else "REJECTED", F["why"], F["dqc"], S["DASH"].get(r, ""),
                                     "Y" if S["DASH"].get(r, "") == ("ACCEPTED" if F["acc"] else "REJECTED") else "N"] for r, F in sorted(FIT.items())], ",")
    rows = []
    for (t, an) in sorted(RES, key=lambda k: (k[0], aix[k[1]])):
        for x in sorted(RES[(t, an)], key=lambda x: x["ord"]):
            rows.append([x["run"], x["inj"], t, an, x["why"], x["df"], x["y"], x["rd"], x["c"], x["fl"], "Y" if x["use"] else "N"])
    O["tube_results.psv"] = _tab(["run_id", "injection_id", "tube", "analyte", "reason", "dilution_factor", "response", "back_calculated", "concentration",
                                    "flag", "used"], rows, "|")
    sch = sorted(((tb[0], tb[1], tb[2], t) for t, tb in S["TUBE"].items() if tb[0] in S["SCOPE"] and tb[2] is not None))
    rows = []
    for s, per, ai, nom, t, an in sorted((s, per, aix[an], nom, t, an) for s, per, nom, t in sch for an in AN):
        rp = REP[(t, an)]
        rows.append([s, per, SEQ[s][per - 1] if s in SEQ else "", an, nom, t, None if rp[0] == "NOT_COLLECTED" else S["EL"][t], rp[2], rp[0], rp[1], rp[3]])
    O["reported_concentrations.csv"] = _tab(["subject_id", "period", "formulation", "analyte", "nominal_h", "tube", "actual_h", "concentration", "status",
                                             "rule", "source_run"], rows, ",")
    x = [f'<sampling_times study="{S["P"]["study_id"]}">']
    for s, per, nom, t in sch:
        tb = S["TUBE"][t]
        d = S["DOSE"].get((s, per))
        dr = S["DRAWU"].get(t) if tb[3] else None
        el = S["EL"][t] if tb[3] else None
        x.append(f'<tube id="{t}" subject="{s}" period="{per}" nominal_h="{nom!r}" dose_utc="{"" if d is None else d.strftime("%Y-%m-%dT%H:%M:%SZ")}" '
                 f'drawn_utc="{"" if dr is None else dr.strftime("%Y-%m-%dT%H:%M:%SZ")}" elapsed_h="{"" if el is None else repr(el)}"/>')
    O["sampling_times.xml"] = "\n".join(x + ["</sampling_times>"]) + "\n"
    lim = float(S["P"]["isr_limit_pct"])
    isr = {}
    for an in AN:
        pairs = []
        for (t, a2), L in sorted(RES.items()):
            if a2 != an or REP[(t, an)][0] != "OK":
                continue
            rr = sorted((v for v in L if v["why"] == "ISR" and v["fl"] == "OK"), key=lambda v: v["ord"])
            if rr:
                o, r_ = REP[(t, an)][2], rr[0]["c"]
                d = (r_ - o) / ((r_ + o) / 2) * 100
                pairs.append({"tube": t, "run_id": rr[0]["run"], "reported": o, "repeat": r_, "diff_pct": d, "within": abs(d) <= lim})
        w = sum(p["within"] for p in pairs)
        isr[an] = {"pairs": pairs, "n_pairs": len(pairs), "n_within": w, "pct_within": w / len(pairs) * 100 if pairs else None,
                   "pass": len(pairs) > 0 and 3 * w >= 2 * len(pairs)}
    O["isr_assessment.json"] = json.dumps({"limit_pct": lim, "analytes": isr})
    rows, lz = [], []
    for (s, per, an) in sorted(NCA, key=lambda k: (k[0], k[1], aix[k[2]])):
        R = NCA[(s, per, an)]
        g = R.get
        rows.append([s, per, SEQ[s][per - 1], an, R["np"], g("cmax"), g("tmax"), g("clast"), g("tlast"), g("auc"), g("lz"), R["n"], g("adj"), g("hl"),
                     g("cp"), g("ai"), g("ex"), R["flag"]])
        lz.append(json.dumps({"subject_id": s, "period": per, "analyte": an, "candidates": R["cand"], "chosen_n": R["n"]}))
    O["nca_parameters.csv"] = _tab(["subject_id", "period", "formulation", "analyte", "n_points", "cmax", "tmax", "clast", "tlast", "auc_last", "lambda_z",
                                    "lz_points", "lz_adj_r2", "half_life", "clast_pred", "auc_inf", "auc_extrap_pct", "flag"], rows, ",")
    O["lambda_z_selection.jsonl"] = "\n".join(lz) + "\n"
    O["be_statistics.json"] = json.dumps(S["BE"])
    md = [f"# {S['P']['study_id']} bioequivalence summary", "", "| analyte | parameter | n | ratio_pct | ci_lower | ci_upper | cv_intra_pct | result |", "|---|---|---|---|---|---|---|---|"]
    for an in AN:
        for prm in S["PRM"]:
            v = S["BE"]["analytes"][an]["parameters"][prm]
            cells = ["", "", "", ""] if v["result"] == "NOT_ESTIMABLE" else [f"{v['ratio_pct_r']:.2f}", f"{v['ci_lower_r']:.2f}", f"{v['ci_upper_r']:.2f}",
                                                                          f"{_half_up(v['cv_intra_pct']):.2f}"]
            md.append("| " + " | ".join([an, prm, str(v["n_TR"] + v["n_RT"])] + cells + [v["result"]]) + " |")
    O["be_summary.md"] = "\n".join(md) + "\n"
    pix = {p: i for i, p in enumerate(S["PRM"])}
    O["analysis_populations.csv"] = _tab(["subject_id", "analyte", "parameter", "included", "reason"],
                                         [[s, an, prm, "N" if w else "Y", w] for (s, an, prm), w in sorted(((k, w) for k, w in S["POP"].items() if k[2] in pix),
                                                                                                           key=lambda kv: (kv[0][0], aix[kv[0][1]], pix[kv[0][2]]))], ",")
    O["excluded_subjects.jsonl"] = "".join(json.dumps(e) + "\n" for e in sorted(S["EX"], key=lambda e: (e["subject_id"], aix[e["analyte"]])))
    rows = []
    for an in AN:
        inc = {s for s in SEQ if not S["POP"][(s, an, "Cmax")]}
        for fm in ("R", "T"):
            grid: dict[float, list] = {}
            for t, tb in S["TUBE"].items():
                if tb[0] in inc and tb[2] is not None and SEQ[tb[0]][tb[1] - 1] == fm and REP[(t, an)][0] in ("OK", "BLQ"):
                    grid.setdefault(tb[2], []).append(REP[(t, an)][2] or 0.0)
            for nm in sorted(grid):
                v = grid[nm]
                m = sum(v) / len(v)
                rows.append([an, fm, nm, len(v), m, math.sqrt(sum((q - m) ** 2 for q in v) / (len(v) - 1)) if len(v) > 1 else None])
    O["mean_profiles.csv"] = _tab(["analyte", "formulation", "nominal_h", "n", "mean", "sd"], rows, ",")
    O["dedup_report.json"] = json.dumps(S["DED"])
    win = {(r["inj"], r["rev"]) for r in S["EFF"].values()}
    O["source_lineage.json"] = json.dumps({"shards": [{"file": c["file"], "layout": c["layout"], "rows": len(rs), "effective": sum((r["inj"], r["rev"]) in win for r in rs)}
                                                      for c, rs in S["SH"]], "inactive": [c["file"] for c in S["CAT"] if c.get("active") is not True]})
    al = set()
    for tk in [r["run"] for _, rs in S["SH"] for r in rs] + [q.get("run", "") for q in S["REQ"]] + [r["run"] for r in S["LOG"]] + \
            [r["target"] for r in S["rul"] if _k(r["action"]) == "REJECT_RUN"]:
        if _k(tk) in S["RA"]:
            al.add(("run", _k(tk), S["RA"][_k(tk)]))
    for tk in S["stoks"]:
        if _k(tk) in S["SA"]:
            al.add(("subject", _k(tk), S["SA"][_k(tk)]))
    for tk in [r["ref"] for _, rs in S["SH"] for r in rs if r["kind"] == "UNK"] + [r["tube"] for r in S["LOG"]] + \
            [r["target"] for r in S["rul"] if _k(r["action"]) == "EXCLUDE_SAMPLE"]:
        if _k(tk) in S["REL"]:
            al.add(("tube", _k(tk), S["REL"][_k(tk)]))
    O["alias_resolution.csv"] = _tab(["kind", "token", "canonical"], [list(a) for a in sorted(al)], ",")
    P = S["P"]
    kv = [("study_id", P["study_id"]), ("nominal_sheet", P["nominal_sheet"]), ("alpha", P["alpha"]), ("ci_level_pct", S["BE"]["ci_level_pct"]),
          ("be_lower_pct", P["be_lower_pct"]), ("be_upper_pct", P["be_upper_pct"]), ("t_quantile_p", S["col"][2:]),
          ("lambda_z_min_points", P["lambda_z_min_points"]), ("lambda_z_adj_r2_tolerance", P["lambda_z_adj_r2_tolerance"]),
          ("extrap_limit_pct", P["extrap_limit_pct"]), ("carryover_limit_pct", P["carryover_limit_pct"]), ("emesis_window_factor", P["emesis_window_factor"]),
          ("emesis_reference_mean_tmax_h", S["med"]), ("emesis_window_h", S["win"]), ("emesis_passes", len(S["passes"])),
          ("emesis_settlement", S["em_settle"]), ("isr_limit_pct", P["isr_limit_pct"])]
    for an in AN:
        m = S["meth"][an]
        kv += [(f"{an}.{k}", m[k]) for k in ("model", "weighting", "std_limit_pct", "lloq_std_limit_pct", "qc_limit_pct")]
    kv += [("conventions_table", "P-1"), ("method_table", "M-2"), ("t_table", "T-1")]
    O["parameters_used.yaml"] = "".join(f"{k}: {'' if v is None else repr(v) if isinstance(v, float) else v}\n" for k, v in kv)
    pub = {}
    for r in S["PUB"]:
        for prm, c in (("Cmax", "cmax"), ("AUClast", "auc_last"), ("AUCinf", "auc_inf")):
            pub[(_k(r["subject"]), int(r["period"]), _k(r["analyte"]), prm)] = _f(r[c]) if r[c] else None
    rec = {}
    for (s, per, an), R in NCA.items():
        rec[(s, per, an, "Cmax")] = R.get("cmax")
        rec[(s, per, an, "AUClast")] = R.get("auc")
        rec[(s, per, an, "AUCinf")] = R.get("ai") if R["flag"] == "OK" else None
    po = {"Cmax": 0, "AUClast": 1, "AUCinf": 2}
    rows = []
    for k in sorted(set(pub) | set(rec), key=lambda k: (k[0], k[1], k[2], po[k[3]])):
        a, b = pub.get(k), rec.get(k)
        if a is None and b is None:
            continue
        d = None if a is None or b is None else (b - a) / a * 100
        st = "ONLY_RECOMPUTED" if a is None else "ONLY_PUBLISHED" if b is None else ("MATCH" if abs(d) <= 1 else "DIFF")
        rows.append([k[0], k[1], k[2], k[3], a, b, d, st])
    O["variance_vs_published.csv"] = _tab(["subject_id", "period", "analyte", "parameter", "published", "recomputed", "diff_pct", "status"], rows, ",")
    ps = {(_k(r["analyte"]), r["parameter"]): r for r in S["PUBS"]["results"]}
    md = [f"# {S['P']['study_id']} published versus recomputed", "", "| analyte | parameter | published_ratio | published_lower | published_upper | published_result | "
          "recomputed_ratio | recomputed_lower | recomputed_upper | recomputed_result |", "|---|---|---|---|---|---|---|---|---|---|"]
    for an in AN:
        for prm in S["PRM"]:
            q = ps.get((an, prm), {})
            v = S["BE"]["analytes"][an]["parameters"][prm]
            pv = ["" if q.get(c) is None else str(q[c]) for c in ("ratio_pct", "ci_lower_pct", "ci_upper_pct")] + [q.get("result", "")]
            rc = ["", "", ""] if v["result"] == "NOT_ESTIMABLE" else [f"{v[c]:.2f}" for c in ("ratio_pct_r", "ci_lower_r", "ci_upper_r")]
            md.append("| " + " | ".join([an, prm] + pv + rc + [v["result"]]) + " |")
    O["reconciliation.md"] = "\n".join(md) + "\n"
    return O


def _st(root: Path, flip: str = "") -> dict[str, Any]:
    k = f"st:{root}:{flip}"
    with _LOCK:
        if k not in _MEMO:
            S = _state(root, flip)
            _stats(S)
            _MEMO[k] = S
        return _MEMO[k]


def derive(root: Path, flip: str = "") -> dict[str, str]:
    k = f"derive:{root}:{flip}"
    with _LOCK:
        if k not in _MEMO:
            _MEMO[k] = _render(_st(root, flip))
        return _MEMO[k]


# =========================================================================== comparison
_INT = re.compile(r"^-?\d+$")
_DEC = re.compile(r"^-?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$")


def _r6(d: Decimal) -> Decimal:
    if d == 0:
        return Decimal(0)
    e = d.adjusted()
    q = Decimal(1).scaleb(e - 5)
    return d.quantize(q, rounding=ROUND_HALF_UP)


def _accept(want: float) -> set[Decimal]:
    d = Decimal(repr(want))
    eps = Decimal("1e-12") * abs(d)
    return {_r6(d), _r6(d - eps), _r6(d + eps)}


def _num_ok(got: Any, want: Any, ref: bool = False) -> bool:
    if isinstance(want, bool) or isinstance(got, bool):
        return isinstance(want, bool) and isinstance(got, bool) and got == want
    try:
        g = got if isinstance(got, Decimal) else Decimal(str(got).strip())
    except ArithmeticError:
        return False
    if not g.is_finite():
        return False
    if isinstance(want, int):
        return g == want
    if ref:
        g = _r6(g)
    return g in _accept(float(want))


def _cell_ok(got: str, want: str, ref: bool = False) -> bool:
    g, w = got.strip(), want.strip()
    if w == "" or g == "":
        return g == w
    if _INT.match(w):
        return bool(_DEC.match(g)) and _num_ok(g, int(w), ref)
    if _DEC.match(w) and ("." in w or "e" in w.lower()):
        return bool(_DEC.match(g)) and _num_ok(g, float(w), ref)
    return g == w


def _json_ok(a: Any, b: Any, ref: bool = False) -> bool:
    if isinstance(b, dict):
        return isinstance(a, dict) and a.keys() == b.keys() and all(_json_ok(a[k], b[k], ref) for k in b)
    if isinstance(b, list):
        return isinstance(a, list) and len(a) == len(b) and all(_json_ok(x, y, ref) for x, y in zip(a, b))
    if b is None or a is None:
        return a is None and b is None
    if isinstance(b, bool) or isinstance(a, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(b, (int, float)):
        return isinstance(a, (int, float)) and _num_ok(Decimal(repr(a)) if isinstance(a, float) else a, b, ref)
    if isinstance(b, str):
        return isinstance(a, str) and a == b
    return False


def _grid(name: str, text: str) -> Any:
    if name.endswith(".xml"):
        r = ET.fromstring(text)
        return [[r.tag] + sorted(r.attrib.items())] + [[c.tag] + sorted(c.attrib.items()) for c in r]
    if name.endswith(".md"):
        out = []
        for x in text.splitlines():
            x = x.strip()
            if x.startswith("|"):
                cells = [c.strip() for c in x.strip("|").split("|")]
                if not all(set(c) <= set("-: ") for c in cells):
                    out.append(cells)
            elif x:
                out.append([" ".join(x.split())])
        return out
    if name.endswith(".yaml"):
        out = {}
        for x in text.splitlines():
            if x.strip() and not x.strip().startswith("#"):
                k, _, v = x.partition(":")
                v = v.strip()
                out[k.strip()] = v[1:-1] if len(v) > 1 and v[0] in "'\"" and v[-1] == v[0] else v
        return [[k, out[k]] for k in sorted(out)]
    sep = {".csv": ",", ".tsv": "\t", ".psv": "|"}[Path(name).suffix]
    return [r for r in csv.reader(io.StringIO(text.lstrip("\ufeff")), delimiter=sep) if r]


def _same(name: str, got: str, want: str, ref: bool = False) -> bool:
    """Compare an output text with a reference text under the H21 number rule (ref=True rounds both sides)."""
    try:
        if name.endswith(".json"):
            return _json_ok(json.loads(got), json.loads(want), ref)
        if name.endswith(".jsonl"):
            ga = [json.loads(x) for x in got.splitlines() if x.strip()]
            wa = [json.loads(x) for x in want.splitlines() if x.strip()]
            return _json_ok(ga, wa, ref)
        ga, wa = _grid(name, got), _grid(name, want)
        if len(ga) != len(wa):
            return False
        for rg, rw in zip(ga, wa):
            if len(rg) != len(rw):
                return False
            for cg, cw in zip(rg, rw):
                if isinstance(cw, tuple):
                    if not (isinstance(cg, tuple) and cg[0] == cw[0] and _cell_ok(cg[1], cw[1], ref)):
                        return False
                elif not (isinstance(cg, str) and _cell_ok(cg, cw, ref)):
                    return False
        return True
    except (ValueError, TypeError, KeyError, ET.ParseError, ArithmeticError, csv.Error, AttributeError):
        return False


