# --------------------------------------------------------------------------- calendar
def _G_offset_at_utc(u: datetime) -> int:
    off = _GBASE_OFFSET
    for when, o in _GTRANSITIONS:
        if u >= when:
            off = o
    return off


def _Gwall_to_utc(w: datetime) -> datetime:
    """Earliest instant whose site offset maps to wall time w; a skipped wall time uses the offset before the jump."""
    cands = []
    for o in sorted({_GBASE_OFFSET} | {o for _, o in _GTRANSITIONS}):
        u = (w - timedelta(hours=o)).replace(tzinfo=_GUTC)
        if _G_offset_at_utc(u) == o:
            cands.append(u)
    if cands:
        return min(cands)
    prev = _GBASE_OFFSET
    for when, o in _GTRANSITIONS:
        if (w - timedelta(hours=prev)).replace(tzinfo=_GUTC) >= when > (w - timedelta(hours=o)).replace(tzinfo=_GUTC):
            return (w - timedelta(hours=prev)).replace(tzinfo=_GUTC)
        prev = o
    raise ValueError(f"unmappable wall time {w}")


def _Gutc_to_wall(u: datetime) -> datetime:
    return (u + timedelta(hours=_G_offset_at_utc(u))).replace(tzinfo=None)


def _Gin_gap(w: datetime) -> bool:
    return not any(_G_offset_at_utc((w - timedelta(hours=o)).replace(tzinfo=_GUTC)) == o for o in {_GBASE_OFFSET} | {o for _, o in _GTRANSITIONS})


def _G_iso_off(u: datetime) -> str:
    o = _G_offset_at_utc(u)
    return _Gutc_to_wall(u).strftime("%Y-%m-%dT%H:%M:%S") + f"+{o:02d}:00"


def _G_z(u: datetime) -> str:
    return u.astimezone(_GUTC).strftime("%Y-%m-%dT%H:%M:%SZ")


def _G_serial(d: date) -> int:
    return (d - (date(1904, 1, 1) if _GCFG["date1904"] else date(1899, 12, 30))).days


# --------------------------------------------------------------------------- writers
def _G_write(path: Path, text: str) -> None:
    path.write_text(text, encoding="utf-8", newline="\n")


def _G_csv_text(header: list[str], rows: list[list[object]], delim: str = ",") -> str:
    buf = io.StringIO()
    w = csv.writer(buf, delimiter=delim, lineterminator="\n")
    w.writerow(header)
    w.writerows(rows)
    return buf.getvalue()


def _G_xesc(s: str) -> str:
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")


def _G_col(i: int) -> str:
    s = ""
    i += 1
    while i:
        i, r = divmod(i - 1, 26)
        s = chr(65 + r) + s
    return s


def _G_xlsx(path: Path, sheets: list[tuple[str, list[list[object]], bool]], file_order: list[int], rng: random.Random) -> None:
    """Real OOXML workbook: shared and inline strings, numeric cells, scrambled part order, hidden sheets."""
    strings: list[str] = []
    index: dict[str, int] = {}

    def sidx(s: str) -> int:
        if s not in index:
            index[s] = len(strings)
            strings.append(s)
        return index[s]

    sheet_xml: list[str] = []
    for _, rows, _hidden in sheets:
        out = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
               '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>']
        for r, row in enumerate(rows, 1):
            cells = []
            for c, val in enumerate(row):
                if val is None or val == "":
                    continue
                ref = f"{_G_col(c)}{r}"
                if isinstance(val, (int, float)) and not isinstance(val, bool):
                    cells.append(f'<c r="{ref}"><v>{val!r}</v></c>' if isinstance(val, float) else f'<c r="{ref}"><v>{val}</v></c>')
                elif rng.random() < 0.18:
                    cells.append(f'<c r="{ref}" t="inlineStr"><is><t>{_G_xesc(str(val))}</t></is></c>')
                else:
                    cells.append(f'<c r="{ref}" t="s"><v>{sidx(str(val))}</v></c>')
            out.append(f'<row r="{r}">' + "".join(cells) + "</row>")
        out.append("</sheetData></worksheet>")
        sheet_xml.append("".join(out))
    n = len(sheets)
    ct = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
          '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">',
          '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>',
          '<Default Extension="xml" ContentType="application/xml"/>',
          '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>',
          '<Override PartName="/xl/sharedStrings.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml"/>',
          '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>']
    for k in range(n):
        ct.append(f'<Override PartName="/xl/worksheets/sheet{k + 1}.xml" '
                  'ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>')
    ct.append("</Types>")
    wb = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
          '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
          'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
          + ('<workbookPr date1904="1"/>' if _GCFG["date1904"] else '<workbookPr defaultThemeVersion="164011"/>') + '<sheets>']
    rels = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">']
    for k, (name, _, hidden) in enumerate(sheets):
        st = ' state="hidden"' if hidden else ""
        wb.append(f'<sheet name="{_G_xesc(name)}" sheetId="{k + 1}"{st} r:id="rId{k + 1}"/>')
        rels.append(f'<Relationship Id="rId{k + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet{file_order[k]}.xml"/>')
    wb.append("</sheets></workbook>")
    rels.append(f'<Relationship Id="rId{n + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings" Target="sharedStrings.xml"/>')
    rels.append(f'<Relationship Id="rId{n + 2}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>')
    rels.append("</Relationships>")
    sst = ['<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
           f'<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="{len(strings)}" uniqueCount="{len(strings)}">']
    sst += [f'<si><t xml:space="preserve">{_G_xesc(s)}</t></si>' for s in strings]
    sst.append("</sst>")
    root_rels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                 '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                 '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
                 '</Relationships>')
    styles = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
              '<fonts count="1"><font><sz val="11"/><name val="Calibri"/></font></fonts>'
              '<fills count="1"><fill><patternFill patternType="none"/></fill></fills>'
              '<borders count="1"><border/></borders>'
              '<cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="1"><xf/></cellXfs>'
              '</styleSheet>')
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as z:
        def put(name: str, data: str) -> None:
            info = zipfile.ZipInfo(name, date_time=(2026, 12, 21, 9, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            z.writestr(info, data)
        put("[Content_Types].xml", "".join(ct))
        put("_rels/.rels", root_rels)
        put("xl/workbook.xml", "".join(wb))
        put("xl/_rels/workbook.xml.rels", "".join(rels))
        put("xl/sharedStrings.xml", "".join(sst))
        put("xl/styles.xml", styles)
        for k in range(n):
            put(f"xl/worksheets/sheet{file_order[k]}.xml", sheet_xml[k])


def _G_pesc(s: str) -> str:
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def _G_pdf(path: Path, pages: list[list[list[str]]], rng: random.Random) -> None:
    """Real PDF 1.4, one Flate content stream per page.

    Every cell is its own text object placed with an absolute Tm matrix, and the objects of a page are
    written in shuffled order, so rows only reappear after grouping by y and ordering by x. Cells are
    literal strings, hexadecimal strings or TJ arrays whose kerning offsets split the string.
    """
    objs: list[bytes] = []
    n_pages = len(pages)
    page_ids = [4 + 2 * p for p in range(n_pages)]
    objs.append(b"<< /Type /Catalog /Pages 2 0 R >>")
    kids = " ".join(f"{i} 0 R" for i in page_ids)
    objs.append(f"<< /Type /Pages /Kids [{kids}] /Count {n_pages} >>".encode())
    objs.append(b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>")
    for p, rows in enumerate(pages):
        ops = []
        y = 806
        for cells in rows:
            for k, cell in enumerate(cells):
                u = rng.random()
                if len(cell) > 3 and u < 0.2:
                    cut = rng.randint(1, len(cell) - 1)
                    show = f"[({_G_pesc(cell[:cut])}) {-rng.randint(8, 30)} ({_G_pesc(cell[cut:])})] TJ"
                elif u < 0.42:
                    show = "<" + cell.encode("latin-1").hex().upper() + "> Tj"
                else:
                    show = f"({_G_pesc(cell)}) Tj"
                ops.append(f"BT /F1 7 Tf 1 0 0 1 {36 + 74 * k} {y} Tm {show} ET")
            y -= 10
        ops.append(f"BT /F1 6 Tf 1 0 0 1 36 24 Tm (Governance memo {_GSTUDY} - page {p + 1} of {n_pages}) Tj ET")
        rng.shuffle(ops)
        raw = ("\n".join(ops) + "\n").encode("latin-1")
        comp = zlib.compress(raw, 9)
        objs.append(f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 3 0 R >> >> /Contents {page_ids[p] + 1} 0 R >>".encode())
        objs.append(f"<< /Length {len(comp)} /Filter /FlateDecode >>\nstream\n".encode() + comp + b"\nendstream")
    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = []
    for i, body in enumerate(objs, 1):
        offsets.append(len(out))
        out += f"{i} 0 obj\n".encode() + body + b"\nendobj\n"
    xref = len(out)
    out += f"xref\n0 {len(objs) + 1}\n0000000000 65535 f \n".encode()
    for off in offsets:
        out += f"{off:010d} 00000 n \n".encode()
    out += f"trailer\n<< /Size {len(objs) + 1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n".encode()
    path.write_bytes(bytes(out))


def _G_paginate(rows: list[list[str]], first: int, rest: int, header: list[str], cont: str) -> list[list[list[str]]]:
    pages = [rows[:first]]
    tail = rows[first:]
    while tail:
        pages.append([[cont], header] + tail[:rest])
        tail = tail[rest:]
    return pages


# --------------------------------------------------------------------------- statistics (author side)
def _G_betacf(a: float, b: float, x: float) -> float:
    tiny = 1e-300
    qab, qap, qam = a + b, a + 1.0, a - 1.0
    c, d = 1.0, 1.0 - qab * x / qap
    d = 1.0 / (d if abs(d) > tiny else tiny)
    h = d
    for m in range(1, 400):
        m2 = 2 * m
        aa = m * (b - m) * x / ((qam + m2) * (a + m2))
        d = 1.0 + aa * d
        d = 1.0 / (d if abs(d) > tiny else tiny)
        c = 1.0 + aa / c
        c = c if abs(c) > tiny else tiny
        h *= d * c
        aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2))
        d = 1.0 + aa * d
        d = 1.0 / (d if abs(d) > tiny else tiny)
        c = 1.0 + aa / c
        c = c if abs(c) > tiny else tiny
        de = d * c
        h *= de
        if abs(de - 1.0) < 1e-16:
            break
    return h


def _G_ibeta(a: float, b: float, x: float) -> float:
    if x <= 0:
        return 0.0
    if x >= 1:
        return 1.0
    lb = math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b) + a * math.log(x) + b * math.log1p(-x)
    if x < (a + 1) / (a + b + 2):
        return math.exp(lb) * _G_betacf(a, b, x) / a
    return 1.0 - math.exp(lb) * _G_betacf(b, a, 1 - x) / b


def _G_tcdf(t: float, df: int) -> float:
    x = df / (df + t * t)
    tail = 0.5 * _G_ibeta(df / 2.0, 0.5, x)
    return 1.0 - tail if t > 0 else tail


def _Gtq(p: float, df: int) -> float:
    lo, hi = 0.0, 1000.0
    for _ in range(200):
        mid = (lo + hi) / 2
        if _G_tcdf(mid, df) < p:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2


def _G_zq(p: float) -> float:
    lo, hi = 0.0, 10.0
    for _ in range(200):
        mid = (lo + hi) / 2
        if 0.5 * math.erfc(-mid / math.sqrt(2)) < p:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2


def _G_wls(xs: list[float], ys: list[float], weighting: str, ncoef: int) -> list[float]:
    """Exact weighted least squares over the float inputs."""
    X = [[Fraction(1), Fraction(x), Fraction(x) * Fraction(x)][:ncoef] for x in xs]
    W = [Fraction(1) / (Fraction(x) * (Fraction(x) if weighting == "1/x^2" else 1)) if weighting != "1" else Fraction(1) for x in xs]
    Y = [Fraction(y) for y in ys]
    A = [[sum(W[i] * X[i][r] * X[i][c] for i in range(len(xs))) for c in range(ncoef)] for r in range(ncoef)]
    B = [sum(W[i] * X[i][r] * Y[i] for i in range(len(xs))) for r in range(ncoef)]
    for col in range(ncoef):
        piv = next(r for r in range(col, ncoef) if A[r][col] != 0)
        A[col], A[piv] = A[piv], A[col]
        B[col], B[piv] = B[piv], B[col]
        for r in range(ncoef):
            if r != col and A[r][col] != 0:
                f = A[r][col] / A[col][col]
                A[r] = [A[r][k] - f * A[col][k] for k in range(ncoef)]
                B[r] -= f * B[col]
    return [float(B[i] / A[i][i]) for i in range(ncoef)]


def _G_inv(coef: list[float], y: float) -> float | None:
    a, b = coef[0], coef[1]
    c = coef[2] if len(coef) > 2 else 0.0
    if c == 0.0:
        return (y - a) / b
    disc = b * b + 4 * c * (y - a)
    if disc < 0:
        return None
    return 2 * (y - a) / (b + math.sqrt(disc))


# --------------------------------------------------------------------------- world
def _G_pk_conc(p: dict, analyte: str, form: str, period: int, t: float) -> float:
    if t <= 0:
        return 0.0
    f = p["F"] * p["iov"][(period, "F")] * (0.96 if form == "T" else 1.0) * (1.04 if period == 2 else 1.0)
    ka = p["ka"] * p["iov"][(period, "ka")] * (0.80 if form == "T" else 1.0)
    ke = p["ke"]
    tau = t - p["tlag"]
    if tau <= 0:
        return 0.0
    if abs(ka - ke) < 1e-3:
        ka += 0.01
    dose = _GDOSE_MG * 1000.0
    if analyte == "VRX":
        return f * dose / p["V"] * ka / (ka - ke) * (math.exp(-ke * tau) - math.exp(-ka * tau))
    km = p["km"]
    if abs(km - ke) < 1e-3:
        km += 0.004
    if abs(km - ka) < 1e-3:
        km += 0.004
    pre = 0.35 * f * dose * ka * ke / p["Vm"]
    return pre * (math.exp(-ke * tau) / ((ka - ke) * (km - ke)) + math.exp(-ka * tau) / ((ke - ka) * (km - ka))
                  + math.exp(-km * tau) / ((ke - km) * (ka - km)))


def _G_world(rng: random.Random) -> dict:
    nb = _GCFG["blocks"]
    subjects = [f"S{i:03d}" for i in range(1, 4 * nb + 1)]
    _G_roles(rng, subjects)
    seq = {}
    for b in range(nb):
        blk = ["TR", "TR", "RT", "RT"]
        rng.shuffle(blk)
        for k in range(4):
            seq[subjects[4 * b + k]] = blk[k]
    group = {s: ("G1" if i < 2 * nb else "G2") for i, s in enumerate(subjects)}
    day = {k: date.fromisoformat(v) for k, v in _GCFG["days"].items()}
    pk = {}
    for s in subjects:
        th = 9.0 * math.exp(rng.gauss(0, 0.22))
        if s in _GSLOW:
            th = rng.uniform(27.0, 33.0)
        pk[s] = {"V": 88.0 * math.exp(rng.gauss(0, 0.25)), "ke": math.log(2) / th, "ka": 1.6 * math.exp(rng.gauss(0, 0.3)),
                 "tlag": rng.uniform(0.05, 0.25), "F": 1.0, "Vm": 120.0 * math.exp(rng.gauss(0, 0.2)),
                 "km": math.log(2) / (13.0 * math.exp(rng.gauss(0, 0.2))),
                 "iov": {(p, k): math.exp(rng.gauss(0, 0.12 if k == "F" else 0.25)) for p in (1, 2) for k in ("F", "ka")}}
    dose_wall = {}
    for g in ("G1", "G2"):
        members = [s for s in subjects if group[s] == g]
        for k, s in enumerate(members):
            for p in (1, 2):
                if p == 2 and s in _GDROPOUTS:
                    continue
                hh, mm = _GCFG["dose_clock"][g]
                dose_wall[(s, p)] = datetime.combine(day[(g, p)], datetime.min.time()) + timedelta(hours=hh, minutes=mm + 3 * k)
    dose_utc = {k: _Gwall_to_utc(v) for k, v in dose_wall.items()}
    form = {}
    for s in subjects:
        form[(s, 1)] = seq[s][0]
        form[(s, 2)] = seq[s][1]
    return {"subjects": subjects, "seq": seq, "group": group, "pk": pk, "dose_wall": dose_wall, "dose_utc": dose_utc, "form": form}


def _G_tubes(rng: random.Random, W: dict) -> None:
    used: set[str] = set()

    def code(prefix: str) -> str:
        while True:
            c = f"{prefix}{rng.randint(100000, 999999)}"
            if c not in used:
                used.add(c)
                return c

    tubes: dict[str, dict] = {}
    for s in W["subjects"]:
        for p in (1, 2):
            if (s, p) not in W["dose_wall"]:
                continue
            for nom in _GNOMS:
                bc = code("VB")
                dw = W["dose_wall"][(s, p)]
                if nom == 0:
                    wall = dw - timedelta(minutes=rng.randint(15, 50))
                else:
                    dev = rng.randint(-2, 7) if rng.random() > 0.05 else rng.randint(12, 35)
                    wall = dw + timedelta(hours=nom, minutes=dev)
                status = "COLLECTED"
                if s == _GMID_P2_WITHDRAW and p == 2 and nom > 24:
                    status = "NOT_COLLECTED"
                tubes[bc] = {"barcode": bc, "subject": s, "period": p, "nom": nom, "status": status, "wall": wall,
                             "utc": _Gwall_to_utc(wall), "where": "main"}
    cands = [b for b, t in tubes.items() if t["status"] == "COLLECTED" and t["nom"] not in (0, 1.5, 2)]
    for b in rng.sample(sorted(cands), 9):
        tubes[b]["status"] = "NOT_COLLECTED"
    for b in rng.sample(sorted(b for b in tubes if tubes[b]["status"] == "COLLECTED"), 34):
        tubes[b]["where"] = "addendum"
    # unscheduled tubes
    dosed = sorted(W["dose_wall"])
    for (s, p), h in zip(rng.sample(dosed, 6), (1.4, 2.3, 6.0, 30.0, 5.0, 14.0)):
        bc = code("VB")
        wall = W["dose_wall"][(s, p)] + timedelta(hours=h, minutes=rng.randint(0, 9))
        tubes[bc] = {"barcode": bc, "subject": s, "period": p, "nom": "UNS", "status": "COLLECTED", "wall": wall,
                     "utc": _Gwall_to_utc(wall), "where": "addendum"}
    W["tubes"] = tubes
    W["used_codes"] = used
    W["code"] = code
    # truth concentrations
    truth = {}
    for bc, t in tubes.items():
        if t["status"] != "COLLECTED":
            continue
        s, p = t["subject"], t["period"]
        el = (t["utc"] - W["dose_utc"][(s, p)]).total_seconds() / 3600.0
        for a in _GANALYTES:
            truth[(bc, a)] = _G_pk_conc(W["pk"][s], a, W["form"][(s, p)], p, el)
    for s, a, frac in _GCARRY:
        pre = [b for b, t in tubes.items() if t["subject"] == s and t["period"] == 2 and t["nom"] == 0][0]
        cm = max(truth[(b, a)] for b, t in tubes.items() if t["subject"] == s and t["period"] == 2 and t["status"] == "COLLECTED" and (b, a) in truth)
        truth[(pre, a)] = frac * cm * 1.035
    W["truth"] = truth


# --------------------------------------------------------------------------- bioanalysis
def _G_lots(rng: random.Random) -> dict:
    lots = {}
    for a, pre in (("VRX", "CS-V"), ("M1", "CS-M")):
        for k in range(1, 5):
            lot = f"{pre}-26{k:02d}"
            lots[lot] = {"analyte": a, "values": [float(f"{t * (1 + rng.uniform(-0.025, 0.025)):.4g}") for t in _GTARGET[a]],
                         "recert": [], "draft": []}
            lots[lot]["recert"] = [float(f"{v * (1 + rng.uniform(-0.006, 0.006)):.4g}") for v in lots[lot]["values"]]
            lots[lot]["draft"] = [float(f"{t * (1 + rng.uniform(-0.04, 0.04)):.3g}") for t in _GTARGET[a]]
    qcl = {}
    for a, pre in (("VRX", "QC-V"), ("M1", "QC-M")):
        for k in range(1, 5):
            lot = f"{pre}-26{k:02d}"
            qcl[lot] = {"analyte": a, "values": {lv: float(f"{t * (1 + rng.uniform(-0.03, 0.03)):.4g}") for lv, t in _GQC_TARGET[a].items()}}
    return {"cal": lots, "qc": qcl}


def _G_curve(rng: random.Random, a: str) -> list[float]:
    if a == "VRX":
        return [0.0006 * (1 + rng.gauss(0, 0.3)), 0.0118 * math.exp(rng.gauss(0, 0.06)), 0.0]
    return [0.0004 * (1 + rng.gauss(0, 0.3)), 0.0152 * math.exp(rng.gauss(0, 0.06)), -3.2e-6 * math.exp(rng.gauss(0, 0.2))]


def _G_ratio(cv: list[float], x: float) -> float:
    return cv[0] + cv[1] * x + cv[2] * x * x


def _G_areas(rng: random.Random, ratio: float) -> tuple[int, int]:
    ist = int(round(rng.gauss(850000, 51000)))
    return int(round(max(ratio, 0.0) * ist)), ist


_GDESIGNS = {"VRX": {2: "qc46", 5: "qc_level", 8: "std12", 11: "lloq_fail", 14: "qc_bad", 17: "ruling", 20: "std11", 23: "assignable"},
           "M1": {3: "qc46", 6: "qc_level", 9: "std12", 12: "lloq_fail", 15: "qc_bad", 18: "ruling", 21: "std11", 24: "assignable"}}


def _G_lab_fit(run: dict, recs: list[dict], lots: dict, a: str) -> dict:
    """The laboratory's own processing (withdrawn Table M-1, target nominals, single-pass exclusion)."""
    model, wt = _GLAB_MODEL[a]
    stds = [r for r in recs if r["stype"] == "STD"]
    xs = [_GTARGET[a][_GLEVELS.index(r["ref"])] for r in stds]
    ys = [r["area_a"] / r["area_is"] for r in stds]
    coef = _G_wls(xs, ys, wt, 2)
    keep = []
    for r, x, y in zip(stds, xs, ys):
        bx = (y - coef[0]) / coef[1]
        lim = 20.0 if r["ref"] == "CS1" else 15.0
        if abs(100 * (bx - x) / x) <= lim:
            keep.append((x, y))
    coef = _G_wls([k[0] for k in keep], [k[1] for k in keep], wt, 2)
    qcs = [r for r in recs if r["stype"] == "QC"]
    qv = lots["qc"][run["qc_lot"]]["values"]
    npass = sum(1 for r in qcs if abs(100 * ((r["area_a"] / r["area_is"] - coef[0]) / coef[1] - qv[r["ref"]]) / qv[r["ref"]]) <= 15.0)
    frac = npass / len(qcs)
    std_frac = len(keep) / len(stds)
    status = "ACCEPTED" if (frac >= 0.67 and std_frac > 0.75 and not run.get("ruling")) else "REJECTED"
    dq = [r for r in recs if r["stype"] == "DQC"]
    dqc_ok = all(abs(100 * ((r["area_a"] / r["area_is"] - coef[0]) / coef[1] * r["df"] - qv["DQC"]) / qv["DQC"]) <= 15.0 for r in dq) and len(dq) >= 2
    return {"coef": coef, "status": status, "qc_pct": round(100 * frac, 1), "std_pct": round(100 * std_frac, 1), "dqc_ok": dqc_ok}


def _G_bioanalysis(rng: random.Random, W: dict) -> None:  # noqa: C901
    lots = _G_lots(rng)
    W["lots"] = lots
    tubes, truth = W["tubes"], W["truth"]
    runs: list[dict] = []
    injections: list[dict] = []
    lims: list[dict] = []
    reassay_log: list[dict] = []
    std_requests: list[dict] = []
    pk_repeat_pick: dict[str, set] = {}
    foreign_codes = [W["code"]("FB") for _ in range(160)]
    group_order = {("G2", 1): 0, ("G1", 1): 1, ("G2", 2): 2, ("G1", 2): 3}
    for a in _GANALYTES:
        order = sorted((b for b, t in tubes.items() if t["status"] == "COLLECTED"),
                       key=lambda b: (group_order[(W["group"][tubes[b]["subject"]], tubes[b]["period"])], tubes[b]["subject"],
                                      99 if tubes[b]["nom"] == "UNS" else tubes[b]["nom"]))
        chunks = [order[i:i + _GCAP] for i in range(0, len(order), _GCAP)]
        spikes = set(rng.sample([b for b in order if tubes[b]["nom"] in (3, 4, 6, 8, 12) and tubes[b]["subject"] not in _GDROPOUTS], 6))
        pk_repeat_pick[a] = spikes
        queue: list[dict] = []
        lab_results: dict[str, list[tuple]] = {}
        cal_lots = [k for k, v in lots["cal"].items() if v["analyte"] == a]
        qc_lots = [k for k, v in lots["qc"].items() if v["analyte"] == a]
        def _plan():
            for k, ch in enumerate(chunks):
                yield ("ORIG", ch)
                if k % 6 == 5:
                    yield ("REASSAY", None)
            guard = 0
            while queue and guard < 14:
                guard += 1
                yield ("REASSAY", None)
            yield ("ISR", None)
            yield ("ISR", None)
        plan = _plan()
        last_dose = max(date.fromisoformat(v) for v in _GCFG["days"].values())
        d0 = last_dose + timedelta(days=5 if a == "VRX" else 6)
        orig_idx = -1
        dqc_fail_done = False
        isr_pool: list[str] = []
        for rtype, items in plan:
            run_id = f"{a}-R{len(_Gruns_of(runs, a)) + 1:03d}"
            design = None
            if rtype == "ORIG":
                orig_idx += 1
                design = _GDESIGNS[a].get(orig_idx - _GCFG["design_shift"])
                work = [{"barcode": b, "df": 1, "reason": "ORIGINAL"} for b in items]
            elif rtype == "REASSAY":
                if not queue:
                    continue
                work, queue = queue[:_GCAP], queue[_GCAP:]
            else:
                if not isr_pool:
                    continue
                work = [{"barcode": b, "df": 1, "reason": "ISR"} for b in isr_pool[:_GCAP]]
                isr_pool = isr_pool[_GCAP:]
            run = {"run_id": run_id, "analyte": a, "run_type": rtype, "cal_lot": cal_lots[(len(_Gruns_of(runs, a)) // 9) % 4],
                   "qc_lot": qc_lots[(len(_Gruns_of(runs, a)) // 11) % 4], "date": d0 + timedelta(days=len(_Gruns_of(runs, a))),
                   "instrument": ["MS-01", "MS-02", "MS-03", "MS-04"][rng.randint(0, 3)], "design": design,
                   "ruling": design == "ruling", "analyst": rng.choice(["AKN", "BLR", "CVD", "DMS", "EPT"])}
            runs.append(run)
            cv = _G_curve(rng, a)
            reps = 3 if design == "qc_level" or (design is None and rng.random() < 0.2) else 2
            cert = lots["cal"][run["cal_lot"]]["values"]
            qv = lots["qc"][run["qc_lot"]]["values"]
            recs: list[dict] = []

            def add(stype: str, ref: str, x: float | None, df: int = 1, blank: str | None = None) -> dict:
                if blank == "BLANK":
                    aa, ii = int(abs(rng.gauss(0, 40))), (0 if rng.random() < 0.5 else int(abs(rng.gauss(0, 300))))
                elif blank == "ZERO":
                    aa, ii = int(abs(rng.gauss(0, 60))), int(round(rng.gauss(850000, 51000)))
                else:
                    aa, ii = _G_areas(rng, _G_ratio(cv, x))
                r = {"inj": f"{run_id}-I{len(recs) + 1:03d}", "run": run_id, "seq": len(recs) + 1, "stype": stype, "ref": ref, "df": df,
                     "area_a": aa, "area_is": ii, "rev": 1, "integ": "AUTO", "void": False, "analyte": a}
                recs.append(r)
                return r

            std_fac = {lv: [1 + rng.gauss(0, 0.045 if lv == "CS1" else 0.025) for _ in range(2)] for lv in _GLEVELS}
            if design == "std12":
                std_fac["CS3"][0] = 1.38
                std_fac["CS5"][1] = 0.66
                std_fac["CS6"][0] = 1.33
                std_fac["CS8"][1] = 0.70
            if design == "std11":
                std_fac["CS2"][0] = 1.42
                std_fac["CS4"][1] = 0.64
                std_fac["CS5"][0] = 1.36
                std_fac["CS7"][0] = 0.68
                std_fac["CS8"][1] = 1.31
            if design == "assignable":
                std_fac["CS4"][0] = 1.52
            qfac = {lv: [1 + rng.gauss(0, 0.03) for _ in range(reps)] for lv in ("LQC", "MQC", "HQC")}
            if design == "qc46":
                qfac["LQC"][0] = 1.24
                qfac["HQC"][1] = 0.78
            if design == "qc_level":
                qfac["HQC"][0] = 1.22
                qfac["HQC"][2] = 0.80
            if design == "qc_bad":
                qfac["LQC"][1] = 0.74
                qfac["MQC"][0] = 1.27
                qfac["HQC"][1] = 1.25
            add("BLANK", "BLANK", None, blank="BLANK")
            add("ZERO", "ZERO", None, blank="ZERO")
            for i, lv in enumerate(_GLEVELS):
                add("STD", lv, cert[i] * std_fac[lv][0])
            for lv in ("LQC", "MQC", "HQC"):
                add("QC", lv, qv[lv] * qfac[lv][0])
            dil = sorted({w["df"] for w in work if w["df"] > 1})
            dq_fac = 1 + rng.gauss(0, 0.03)
            if dil and a == "VRX" and not dqc_fail_done and rtype == "REASSAY":
                dq_fac = 1.21
                dqc_fail_done = True
            for d in dil:
                add("DQC", "DQC", qv["DQC"] / d * dq_fac, df=d)
            fore = rng.sample(foreign_codes, 4) if rtype == "ORIG" else []
            unk = list(work)
            for fc in fore:
                unk.insert(rng.randint(0, len(unk)), {"barcode": fc, "df": 1, "reason": "FOREIGN"})
            half = len(unk) // 2
            for j, w in enumerate(unk):
                if j == half:
                    for lv in ("LQC", "MQC", "HQC"):
                        add("QC", lv, qv[lv] * qfac[lv][1])
                if w["reason"] == "FOREIGN":
                    x = rng.uniform(0.5, 300) if a == "VRX" else rng.uniform(0.2, 90)
                else:
                    x = truth[(w["barcode"], a)] / w["df"]
                    if x > 0:
                        x *= 1 + rng.gauss(0, 0.035)
                        x += rng.gauss(0, 0.02 * _GTARGET[a][0])
                    else:
                        x = abs(rng.gauss(0, 0.04 * _GTARGET[a][0]))
                    if w["reason"] == "ORIGINAL" and w["barcode"] in spikes:
                        x *= 1.7
                    if w["reason"] == "ISR" and rng.random() < 0.09:
                        x *= 1.32
                r = add("UNK", w["barcode"], max(x, 0.0), df=w["df"])
                r["reason"] = w["reason"]
            if reps == 3:
                for lv in ("LQC", "MQC", "HQC"):
                    add("QC", lv, qv[lv] * qfac[lv][2])
            for d in dil:
                add("DQC", "DQC", qv["DQC"] / d * (1 + rng.gauss(0, 0.03)), df=d)
            for i, lv in enumerate(_GLEVELS):
                add("STD", lv, cert[i] * std_fac[lv][1])
            add("BLANK", "BLANK", None, blank="BLANK")
            # analyst exclusion requests
            if design == "assignable":
                cs4 = [r for r in recs if r["stype"] == "STD" and r["ref"] == "CS4"][0]
                cs7 = [r for r in recs if r["stype"] == "STD" and r["ref"] == "CS7"][1]
                std_requests.append({"run": run_id, "inj": cs4["inj"], "code": "INJ_FAIL", "status": "APPROVED"})
                std_requests.append({"run": run_id, "inj": cs7["inj"], "code": "OUTLIER", "status": "APPROVED"})
            elif design == "lloq_fail":
                for st_, code in zip([r for r in recs if r["stype"] == "STD" and r["ref"] == "CS1"], ("INJ_FAIL", "VIAL_SWAP")):
                    std_requests.append({"run": run_id, "inj": st_["inj"], "code": code, "status": "APPROVED"})
            elif design is None and rng.random() < 0.55:
                st = rng.choice([r for r in recs if r["stype"] in ("STD", "QC")])
                std_requests.append({"run": run_id, "inj": st["inj"],
                                     "code": rng.choice(["INJ_FAIL", "PIPETTE_ERR", "OUTLIER", "CURVE_FIT", "LOW_IS", "VIAL_SWAP"]),
                                     "status": rng.choice(["APPROVED", "APPROVED", "REJECTED", "PENDING", "approved"])})
            lab = _G_lab_fit(run, recs, lots, a)
            run["lab"] = lab
            injections.extend(recs)
            # laboratory decisions on study samples
            for r in recs:
                if r["stype"] != "UNK" or r["reason"] == "FOREIGN":
                    continue
                y = r["area_a"] / r["area_is"]
                x = (y - lab["coef"][0]) / lab["coef"][1]
                flag = "OK"
                if x < _GTARGET[a][0]:
                    flag = "BLQ"
                elif x > _GTARGET[a][-1]:
                    flag = "ALQ"
                conc = x * r["df"] if flag == "OK" else None
                if r["df"] > 1 and not lab["dqc_ok"]:
                    flag = "DQC_FAIL"
                    conc = None
                lims.append({"run": run_id, "tube": r["ref"], "analyte": a, "conc": None if conc is None else round(conc, 4), "flag": flag,
                             "run_status": lab["status"], "reason": r["reason"], "df": r["df"], "seq": r["seq"]})
                lab_results.setdefault(r["ref"], []).append((run_id, lab["status"], flag, conc, r["reason"]))
                if lab["status"] == "REJECTED":
                    if r["reason"] in ("ORIGINAL", "RUN_FAIL"):
                        queue.append({"barcode": r["ref"], "df": 1, "reason": "RUN_FAIL"})
                    elif r["reason"] == "ALQ":
                        queue.append({"barcode": r["ref"], "df": r["df"], "reason": "ALQ"})
                    continue
                if r["reason"] in ("ORIGINAL", "RUN_FAIL") and flag == "ALQ":
                    queue.append({"barcode": r["ref"], "df": 10, "reason": "ALQ"})
                if r["reason"] == "ALQ" and flag == "DQC_FAIL":
                    queue.append({"barcode": r["ref"], "df": 5, "reason": "ALQ"})
                if r["reason"] == "ORIGINAL" and r["ref"] in spikes:
                    queue.append({"barcode": r["ref"], "df": 1, "reason": "PK_REPEAT"})
                    queue.append({"barcode": r["ref"], "df": 1, "reason": "PK_REPEAT"})
                if r["reason"] in ("ORIGINAL",) and flag == "OK" and conc and conc > 3 * _GTARGET[a][0] and rng.random() < 0.075:
                    isr_pool.append(r["ref"])
            if design == "qc_level":
                # QA audit later ordered a reanalysis of this run anyway
                queued = {q["barcode"] for q in queue}
                for r in recs:
                    if r["stype"] == "UNK" and r["reason"] == "ORIGINAL" and r["ref"] not in queued:
                        queue.append({"barcode": r["ref"], "df": 1, "reason": "RUN_FAIL"})
            for r in recs:
                if r["stype"] == "UNK" and r["reason"] not in ("ORIGINAL", "FOREIGN"):
                    reassay_log.append({"tube": r["ref"], "analyte": a, "run": run_id, "reason": r["reason"], "status": "COMPLETED",
                                        "requested": (run["date"] - timedelta(days=rng.randint(1, 4)))})
        W.setdefault("lab_results", {})[a] = lab_results
    W["runs"] = runs
    W["injections"] = injections
    W["lims"] = lims
    W["reassay_log"] = reassay_log
    W["std_requests"] = std_requests
    W["foreign"] = foreign_codes
    W["pk_repeat"] = pk_repeat_pick


def _Gruns_of(runs: list[dict], a: str) -> list[dict]:
    return [r for r in runs if r["analyte"] == a]


def _G_reprocess(rng: random.Random, W: dict) -> None:
    """Later reintegrations (revisions), voids and the audit trail."""
    inj = W["injections"]
    extra: list[dict] = []
    audit: list[dict] = []
    designed = {r["run_id"] for r in W["runs"] if r["design"]}
    eid = 1000
    for r in inj:
        u = rng.random()
        if r["stype"] == "UNK" and u < 0.045:
            mode = "MANUAL" if rng.random() < 0.7 else "AUTO"
            n = dict(r, rev=2, integ=mode, area_a=int(round(r["area_a"] * (1 + rng.uniform(-0.08, 0.08)))))
            extra.append(n)
            if mode == "MANUAL":
                kind = rng.random()
                ts = datetime(2026, 12, 1, 9, 0, tzinfo=_GUTC) + timedelta(minutes=rng.randint(0, 20000))
                if kind < 0.68:
                    audit.append({"inj": r["inj"], "rev": 2, "code": rng.choice(["BASELINE_DRIFT", "SPLIT_PEAK", "SHOULDER", "NOISE_SPIKE"]), "status": "APPROVED", "ts": ts})
                    if rng.random() < 0.15:
                        audit.append({"inj": r["inj"], "rev": 2, "code": "BASELINE_DRIFT", "status": "REJECTED", "ts": ts - timedelta(hours=5)})
                elif kind < 0.80:
                    audit.append({"inj": r["inj"], "rev": 2, "code": rng.choice(["ANALYST_PREF", "MATCH_EXPECTED", "PEAK_WIDTH"]), "status": "APPROVED", "ts": ts})
                elif kind < 0.90:
                    audit.append({"inj": r["inj"], "rev": 2, "code": "SPLIT_PEAK", "status": "REJECTED", "ts": ts})
                    if rng.random() < 0.4:
                        audit.append({"inj": r["inj"], "rev": 2, "code": "SPLIT_PEAK", "status": "APPROVED", "ts": ts - timedelta(hours=3)})
                elif kind < 0.95:
                    audit.append({"inj": r["inj"], "rev": 2, "code": "SHOULDER", "status": "PENDING", "ts": ts})
            if rng.random() < 0.12:
                n3 = dict(n, rev=3, integ="AUTO", area_a=int(round(n["area_a"] * (1 + rng.uniform(-0.03, 0.03)))))
                extra.append(n3)
        elif r["stype"] in ("STD", "QC") and r["run"] not in designed and u < 0.02:
            extra.append(dict(r, rev=2, integ="MANUAL", area_a=int(round(r["area_a"] * (1 + rng.uniform(-0.02, 0.02))))))
            audit.append({"inj": r["inj"], "rev": 2, "code": "BASELINE_DRIFT", "status": rng.choice(["APPROVED", "APPROVED", "REJECTED"]),
                          "ts": datetime(2026, 12, 2, 10, 0, tzinfo=_GUTC) + timedelta(minutes=rng.randint(0, 9000))})
        elif r["stype"] in ("UNK", "BLANK", "ZERO") and 0.045 <= u < 0.057:
            extra.append(dict(r, rev=2, void=True))
        elif r["stype"] == "UNK" and 0.057 <= u < 0.063:
            # first entry voided at acquisition, re-entered as revision 2
            r["void"] = True
            extra.append(dict(r, rev=2, void=False, area_a=int(round(r["area_a"] * (1 + rng.uniform(-0.02, 0.02))))))
        if r["stype"] == "UNK" and rng.random() < 0.01:
            audit.append({"inj": r["inj"], "rev": 1, "code": "NONE", "status": "APPROVED",
                          "ts": datetime(2026, 11, 30, 8, 0, tzinfo=_GUTC) + timedelta(minutes=rng.randint(0, 9000))})
    for a in audit:
        eid += 1
        a["id"] = f"AT{eid}"
    W["revisions"] = extra
    W["audit"] = audit


def _G_relabels(rng: random.Random, W: dict) -> None:
    tubes = W["tubes"]
    rel = []
    cand = sorted(b for b, t in tubes.items() if t["status"] == "COLLECTED")
    nrel = _GCFG["relabels"]
    picks = rng.sample(cand, nrel + 8)
    newmap = {}
    for b in picks[:nrel]:
        nb = W["code"]("VR")
        newmap[b] = nb
        rel.append({"old": b, "new": nb, "status": "ACTIVE", "when": datetime(2026, 11, 10, 8, 0, tzinfo=_GUTC) + timedelta(minutes=rng.randint(0, 2000))})
    for b in picks[nrel:]:
        other = rng.choice([c for c in cand if c != b and c not in newmap])
        rel.append({"old": b, "new": other, "status": "CANCELLED", "when": datetime(2026, 11, 10, 8, 0, tzinfo=_GUTC) + timedelta(minutes=rng.randint(0, 2000))})
    W["relabel"] = rel
    W["newcode"] = newmap
    for r in W["injections"] + W["revisions"]:
        if r["stype"] == "UNK" and r["ref"] in newmap:
            r["ref"] = newmap[r["ref"]]


# --------------------------------------------------------------------------- tokens
def _G_run_token(run_id: str, style: int) -> str:
    a, n = run_id.split("-R")
    k = int(n)
    return [run_id, run_id.lower(), f"R{n}/{a}", f"BR-{a}-{k:03d}", f"{a}_R{n}", f" {run_id} "][style]


def _G_subj_token(s: str, style: int) -> str:
    k = int(s[1:])
    return [s, s.lower(), f"S-{k:03d}", f"{_GSTUDY}-{k:03d}", f"{k:03d}", f"Subj {k}"][style]


def _G_level_token(ref: str, style: int) -> str:
    if ref.startswith("CS"):
        k = ref[2:]
        return [ref, f"STD-{k}", f"L{k}", f"Cal {k}"][style]
    m = {"LQC": ["LQC", "QC-L", "low", "QCL"], "MQC": ["MQC", "QC-M", "mid", "QCM"], "HQC": ["HQC", "QC-H", "high", "QCH"],
         "DQC": ["DQC", "QC-D", "dil", "QCD"], "BLANK": ["BLANK", "BLK", "blank", "BLANK"], "ZERO": ["ZERO", "ZERO", "zero", "Z0"]}
    return m[ref][style]


# layout id -> (type tokens STD,QC,DQC,UNK,BLANK,ZERO ; level style ; run style ; df style ; live/void tokens)
_GLAYOUTS = {
    "i_csv": (("STD", "QC", "DQC", "UNK", "BLANK", "ZERO"), 0, 0, "plain", ("OK", "VOID")),
    "i_tsv": (("Standard", "QC", "DilQC", "Unknown", "Blank", "Zero"), 1, 1, "plain", ("0", "9")),
    "i_psv": (("std", "qc", "dqc", "unk", "blank", "zero"), 2, 2, "plain", ("live", "dead")),
    "i_jsonl": (("STD", "QC", "DQC", "SAMPLE", "BLANK", "ZERO"), 0, 3, "ratio", ("valid", "void")),
    "i_ndjson": (("cal", "qc", "dilqc", "study", "blank", "zero"), 3, 4, "num", (False, True)),
    "i_xml": (("STD", "QC", "DQC", "UNK", "BLANK", "ZERO"), 1, 0, "plain", ("valid", "voided")),
    "i_sqlite": (("S", "Q", "D", "U", "B", "Z"), 0, 2, "num", (0, 1)),
    "i_db": (("STD", "QC", "DQC", "UNK", "BLK", "ZERO"), 2, 1, "num", ("V", "X")),
    "i_json": (("Standard", "QC", "DilQC", "Unknown", "Blank", "Zero"), 0, 3, "plain", ("ACTIVE", "RETRACTED")),
    "i_yaml": (("STD", "QC", "DQC", "UNK", "BLANK", "ZERO"), 3, 0, "x", ("L", "V")),
    "i_yml": (("std", "qc", "dqc", "unk", "blank", "zero"), 1, 4, "x", ("ok", "cxl")),
    "i_txt": (("STD", "QC", "DQC", "UNK", "BLANK", "ZERO"), 2, 2, "ratio", ("A", "X")),
    "i_csvsemi": (("STD", "QC", "DQC", "UNK", "BLANK", "ZERO"), 0, 1, "plain", ("Y", "N")),
    "i_tsv2": (("STD", "QC", "DQC", "UNK", "BLANK", "ZERO"), 0, 0, "plain", ("ok", "void")),
    "i_jsonl2": (("STD", "QC", "DQC", "UNK", "BLANK", "ZERO"), 0, 3, "num", ("ok", "void")),
    "i_psv2": (("S", "Q", "D", "U", "B", "Z"), 1, 4, "plain", ("KEEP", "DROP")),
}
_GSTYPES = ("STD", "QC", "DQC", "UNK", "BLANK", "ZERO")


def _G_df_tok(df: int, style: str) -> object:
    if style == "plain":
        return str(df)
    if style == "ratio":
        return f"1:{df}"
    if style == "x":
        return f"x{df}"
    return df


def _G_kc(v: int, comma: bool = False) -> str:
    s = f"{v / 1000:.3f}"
    return s.replace(".", ",") if comma else s


def _G_fields(r: dict, lay: str, rng: random.Random) -> dict:
    types, lst, rst, dfs, st = _GLAYOUTS[lay]
    t = types[_GSTYPES.index(r["stype"])]
    if r["stype"] == "UNK":
        ref = r["ref"].lower() if rng.random() < 0.08 else r["ref"]
    else:
        ref = _G_level_token(r["ref"], lst)
    inj = r["inj"].lower() if rng.random() < 0.06 else r["inj"]
    return {"inj": inj, "run": _G_run_token(r["run"], rst), "seq": r["seq"], "type": t, "ref": ref, "df": _G_df_tok(r["df"], dfs),
            "a": r["area_a"], "is": r["area_is"], "integ": r["integ"], "rev": r["rev"], "st": st[1] if r["void"] else st[0]}


def _G_write_shard(path: Path, lay: str, recs: list[dict], rng: random.Random) -> int:  # noqa: C901
    rows = [_G_fields(r, lay, rng) for r in recs]
    if lay == "i_csv":
        _G_write(path, _G_csv_text(["injection_id", "run_ref", "seq", "sample_type", "sample_ref", "dilution", "analyte_area", "is_area", "integration", "revision", "state"],
                               [[f["inj"], f["run"], f["seq"], f["type"], f["ref"], f["df"], f["a"], f["is"], f["integ"], f["rev"], f["st"]] for f in rows]))
    elif lay == "i_tsv":
        _G_write(path, _G_csv_text(["INJ", "RUN", "SEQ", "TYPE", "REF", "DIL", "A_AREA", "IS_AREA", "INTEG", "REV", "ST"],
                               [[f["inj"], f["run"], f["seq"], f["type"], f["ref"], f["df"], f["a"], f["is"], f["integ"][0], f["rev"], f["st"]] for f in rows], "\t"))
    elif lay == "i_psv":
        _G_write(path, _G_csv_text(["inj", "run", "seq", "kind", "ref", "df", "area_counts", "is_area_kcounts", "int", "rev", "status"],
                               [[f["inj"], f["run"], f["seq"], f["type"], f["ref"], f["df"], f["a"], _G_kc(f["is"]), f["integ"].lower(), f["rev"], f["st"]] for f in rows], "|"))
    elif lay == "i_jsonl":
        _G_write(path, "".join(json.dumps({"injectionId": f["inj"], "runRef": f["run"], "seqNo": f["seq"], "sampleType": f["type"], "sampleRef": f["ref"],
                                         "dilutionFactor": f["df"], "analyteArea": f["a"], "isArea": f["is"], "integration": f["integ"],
                                         "revision": f["rev"], "status": f["st"]}) + "\n" for f in rows))
    elif lay == "i_ndjson":
        _G_write(path, "".join(json.dumps({"id": f["inj"], "run": f["run"], "order": f["seq"], "sample": {"type": f["type"], "ref": f["ref"], "df": f["df"]},
                                         "areas": {"analyte": f["a"], "istd": f["is"]}, "proc": {"mode": f["integ"][0], "rev": f["rev"]},
                                         "void": f["st"]}) + "\n" for f in rows))
    elif lay == "i_xml":
        out = ['<?xml version="1.0" encoding="UTF-8"?>', '<injections source="MS export" schema="2">']
        for f in rows:
            out.append(f'  <inj id="{_G_xesc(f["inj"])}" run="{_G_xesc(f["run"])}" seq="{f["seq"]}" type="{f["type"]}" ref="{_G_xesc(f["ref"])}" df="{f["df"]}" '
                       f'rev="{f["rev"]}" integ="{f["integ"]}" status="{f["st"]}"><area kind="analyte">{f["a"]}</area><area kind="istd">{f["is"]}</area></inj>')
        out.append("</injections>")
        _G_write(path, "\n".join(out) + "\n")
    elif lay == "i_sqlite":
        con = sqlite3.connect(path)
        con.execute("create table injection (inj_id text, run_token text, seq integer, stype text, sref text, dil integer, a_area integer, is_area integer, integ text, rev integer, voided integer)")
        con.executemany("insert into injection values (?,?,?,?,?,?,?,?,?,?,?)",
                        [(f["inj"], f["run"], f["seq"], f["type"], f["ref"], f["df"], f["a"], f["is"], f["integ"], f["rev"], f["st"]) for f in rows])
        con.commit()
        con.close()
    elif lay == "i_db":
        con = sqlite3.connect(path)
        con.execute("create table inj (id text, run text, seq integer, stype text, sref text, dil integer, integ text, rev integer, flag text)")
        con.execute("create table area (inj_id text, rev integer, channel text, value integer)")
        con.executemany("insert into inj values (?,?,?,?,?,?,?,?,?)", [(f["inj"], f["run"], f["seq"], f["type"], f["ref"], f["df"], f["integ"], f["rev"], f["st"]) for f in rows])
        arows = []
        for f in rows:
            arows.append((f["inj"], f["rev"], "IS", f["is"]))
            arows.append((f["inj"], f["rev"], "A", f["a"]))
        rng.shuffle(arows)
        con.executemany("insert into area values (?,?,?,?)", arows)
        con.commit()
        con.close()
    elif lay == "i_json":
        cols = ["inj", "run", "seq", "type", "ref", "df", "area_analyte", "area_istd", "integration", "rev", "state"]
        _G_write(path, json.dumps({"export": {"system": "MassLynx bridge", "columns": cols,
                                            "rows": [[f["inj"], f["run"], f["seq"], f["type"], f["ref"], f["df"], f["a"], f["is"], f["integ"], f["rev"], f["st"]] for f in rows]}}, indent=1) + "\n")
    elif lay == "i_yaml":
        out = ["# instrument export (yaml)", "injections:"]
        for f in rows:
            out += [f"  - inj: {f['inj']}", f"    run: \"{f['run']}\"", f"    seq: {f['seq']}", f"    type: {f['type']}", f"    ref: \"{f['ref']}\"",
                    f"    df: {f['df']}", f"    area_a: {f['a']}", f"    area_is: {f['is']}", f"    integ: {f['integ']}", f"    rev: {f['rev']}", f"    st: {f['st']}"]
        _G_write(path, "\n".join(out) + "\n")
    elif lay == "i_yml":
        out = ["records:"]
        for f in rows:
            out += [f"- injection: {f['inj']}", f"  batch: \"{f['run']}\"", f"  position: {f['seq']}", f"  kind: {f['type']}", f"  label: \"{f['ref']}\"",
                    f"  dilution: {f['df']}", f"  analyte_counts: {f['a']}", f"  istd_kcounts: {_G_kc(f['is'])}", f"  mode: {f['integ'].lower()}",
                    f"  revision: {f['rev']}", f"  state: {f['st']}"]
        _G_write(path, "\n".join(out) + "\n")
    elif lay == "i_txt":
        out = ["# key=value export, one injection per line", "# fields: INJ RUN SEQ TYPE REF DF AREA ISAREA MODE REV ST"]
        for f in rows:
            out.append(f"INJ={f['inj']}; RUN={f['run']}; SEQ={f['seq']}; TYPE={f['type']}; REF={f['ref']}; DF={f['df']}; AREA={f['a']}; "
                       f"ISAREA={f['is']}; MODE={f['integ']}; REV={f['rev']}; ST={f['st']}")
        _G_write(path, "\n".join(out) + "\n")
    elif lay == "i_csvsemi":
        _G_write(path, _G_csv_text(["Injection", "Batch", "Pos", "Type", "Sample", "Dilution", "Area (kcounts)", "IS Area (kcounts)", "Integration", "Rev", "Valid"],
                               [[f["inj"], f["run"], f["seq"], f["type"], f["ref"], f["df"], _G_kc(f["a"], True), _G_kc(f["is"], True), f["integ"], f["rev"], f["st"]] for f in rows], ";"))
    elif lay == "i_tsv2":
        _G_write(path, _G_csv_text(["injection", "revision", "integration", "analyte_area", "is_area", "status", "run", "seq", "type", "ref", "df"],
                               [[f["inj"], f["rev"], f["integ"], f["a"], f["is"], f["st"], f["run"], f["seq"], f["type"], f["ref"], f["df"]] for f in rows], "\t"))
    elif lay == "i_jsonl2":
        _G_write(path, "".join(json.dumps({"inj": f["inj"], "rev": f["rev"], "mode": f["integ"], "a": f["a"], "is": f["is"], "st": f["st"], "run": f["run"],
                                         "seq": f["seq"], "type": f["type"], "ref": f["ref"], "df": f["df"]}) + "\n" for f in rows))
    elif lay == "i_psv2":
        _G_write(path, _G_csv_text(["inj", "run", "pos", "t", "ref", "df", "area", "is_area", "integ", "rev", "keep"],
                               [[f["inj"], f["run"], f["seq"], f["type"], f["ref"], f["df"], f["a"], f["is"], f["integ"], f["rev"], f["st"]] for f in rows], "|"))
    return len(rows)


_GSHARDS = [("xk_41ra.csv", "i_csv"), ("pv_7d2m.tsv", "i_tsv"), ("qa_m3k8.psv", "i_psv"), ("hb_2wz0.jsonl", "i_jsonl"),
          ("ty_9fe1.ndjson", "i_ndjson"), ("lc_5nq4.xml", "i_xml"), ("rd_8vv3.sqlite", "i_sqlite"), ("mz_0kt6.db", "i_db"),
          ("wf_3hc9.json", "i_json"), ("gn_6pt2.yaml", "i_yaml"), ("uj_1sx5.yml", "i_yml"), ("oc_4bb7.txt", "i_txt"),
          ("ze_2mm9.csv", "i_csvsemi"), ("bt_7ye4.psv", "i_psv2"), ("fs_8qq1.tsv", "i_tsv2"), ("kv_5jj3.jsonl", "i_jsonl2")]


def _G_write_shards(rng: random.Random, W: dict, data: Path) -> list[dict]:
    primary = [s for s in _GSHARDS if s[1] not in ("i_tsv2", "i_jsonl2")]
    runs = sorted(W["runs"], key=lambda r: (r["date"], r["run_id"]))
    by_run: dict[str, list[dict]] = {}
    for r in W["injections"]:
        by_run.setdefault(r["run"], []).append(r)
    assign = {}
    for i, run in enumerate(runs):
        assign[run["run_id"]] = primary[(i * 5 + rng.randint(0, 2)) % len(primary)][0]
    content: dict[str, list[dict]] = {f: [] for f, _ in _GSHARDS}
    for run in runs:
        content[assign[run["run_id"]]].extend(by_run[run["run_id"]])
    rv = W["revisions"]
    for r in rv:
        if rng.random() < 0.25:
            content[assign[r["run"]]].append(r)
        else:
            content["fs_8qq1.tsv" if rng.random() < 0.5 else "kv_5jj3.jsonl"].append(r)
    # exact duplicates of revision-1 records in the reprocessing exports
    for r in rng.sample(W["injections"], 140):
        content["fs_8qq1.tsv" if rng.random() < 0.5 else "kv_5jj3.jsonl"].append(r)
    cat = []
    for f, lay in _GSHARDS:
        recs = content[f]
        rng.shuffle(recs) if lay in ("i_tsv2", "i_jsonl2", "i_psv2") else None
        n = _G_write_shard(data / f, lay, recs, rng)
        cat.append({"file": f, "layout": lay, "stream": "injections", "active": True, "rows": n})
    # retired shard: an early export of four runs before reintegration, different area values
    old_runs = [r["run_id"] for r in runs[3:7]]
    old = [dict(r, area_a=int(round(r["area_a"] * (1 + rng.uniform(-0.12, 0.12))))) for r in W["injections"] if r["run"] in old_runs]
    _G_write_shard(data / "ab_0re7.csv", "i_csv", old, rng)
    cat.insert(9, {"file": "ab_0re7.csv", "layout": "i_csv", "stream": "injections", "active": False, "rows": len(old),
                   "note": "superseded by the reintegrated export"})
    # validation export (not a study feed)
    vrows = []
    for k in range(260):
        lv = _GLEVELS[k % 8]
        a = _GANALYTES[k % 2]
        x = _GTARGET[a][k % 8]
        vrows.append([f"MV-{a}-{k // 16 + 1:02d}-I{k % 16 + 1:03d}", f"MV-{a}-{k // 16 + 1:02d}", k % 16 + 1, "STD", lv, 1,
                      int(round((0.0005 + 0.012 * x) * 840000 * (1 + rng.gauss(0, 0.02)))), int(round(rng.gauss(840000, 40000))), "AUTO", 1, "OK"])
    _G_write(data / "mv_runs_export.csv", _G_csv_text(["injection_id", "run_ref", "seq", "sample_type", "sample_ref", "dilution", "analyte_area", "is_area",
                                                   "integration", "revision", "state"], vrows))
    W["assign"] = assign
    return cat


# --------------------------------------------------------------------------- clinical files
def _G_nom_txt(nom: object) -> str:
    return "UNS" if nom == "UNS" else f"{nom:g}"


def _G_write_clinical(rng: random.Random, W: dict, data: Path) -> None:  # noqa: C901
    tubes = W["tubes"]
    subj_tok: dict[str, set] = {}

    def st(s: str, styles: tuple) -> str:
        t = _G_subj_token(s, rng.choice(styles))
        subj_tok.setdefault(s, set()).add(t)
        return t

    # manifests
    main_rows = []
    for b, t in sorted(tubes.items(), key=lambda kv: (kv[1]["subject"], kv[1]["period"], str(kv[1]["nom"]))):
        if t["where"] != "main":
            continue
        nom = "PRE" if t["nom"] == 0 and rng.random() < 0.6 else _G_nom_txt(t["nom"])
        stat = t["status"] if rng.random() > 0.1 else t["status"].lower().replace("_", " ")
        main_rows.append([b, st(t["subject"], (0, 2)), t["period"], nom, stat, rng.choice(["K2EDTA 4 mL", "K2EDTA 2 mL"]),
                          _G_z(datetime(2026, 10, 1, 8, tzinfo=_GUTC) + timedelta(minutes=rng.randint(0, 9000)))])
    _G_write(data / "tube_manifest_main.csv", _G_csv_text(["tube_id", "subject", "period", "nominal_h", "status", "tube_type", "registered_at"], main_rows))
    out = ["# late tube registrations (re-labelled racks, recollections and unscheduled draws)", "study: " + _GSTUDY, "tubes:"]
    for b, t in sorted(tubes.items()):
        if t["where"] != "addendum":
            continue
        nom = t["nom"]
        out += [f"  - tube: {b}", f"    subject: \"{st(t['subject'], (0, 1, 2))}\"", f"    period: {t['period']}",
                f"    nominal_h: \"{_G_nom_txt(nom)}\"" if nom == "UNS" else f"    nominal_h: {_G_nom_txt(nom)}",
                f"    status: {t['status']}", f"    note: \"{'unscheduled draw' if nom == 'UNS' else 'registered late'}\""]
    _G_write(data / "tube_manifest_addendum.yaml", "\n".join(out) + "\n")
    # relabel journal
    out = ['<?xml version="1.0" encoding="UTF-8"?>', f'<relabel_journal study="{_GSTUDY}">']
    for e in sorted(W["relabel"], key=lambda e: e["when"]):
        old = e["old"].lower() if rng.random() < 0.2 else e["old"]
        out.append(f'  <relabel old="{old}" new="{e["new"]}" status="{e["status"]}" at="{_G_z(e["when"])}" reason="{rng.choice(["label smudged", "rack swap", "printer fault"])}"/>')
    for k in range(170):
        out.append(f'  <relabel old="FB{100000 + k * 37}" new="FR{200000 + k * 41}" status="ACTIVE" at="2026-11-0{1 + k % 8}T10:00:00Z" reason="other study {_GOTHER}" study="{_GOTHER}"/>')
    out.append("</relabel_journal>")
    _G_write(data / "tube_relabel_journal.xml", "\n".join(out) + "\n")
    # dosing
    rows = []
    for s in W["subjects"]:
        if (s, 1) not in W["dose_wall"]:
            continue
        dw = W["dose_wall"][(s, 1)]
        tok = st(s, (3,))
        kit = f"K-{W['form'][(s, 1)]}-{rng.randint(1000, 9999)}"
        rows.append([tok, 1, "FAST_START", (dw - timedelta(hours=10)).strftime("%Y-%m-%d %H:%M"), "", kit, "overnight fast"])
        rows.append([tok, 1, "DOSE", dw.strftime("%Y-%m-%d %H:%M"), f"{_GDOSE_MG:g}", kit, "tablet with 240 mL water"])
        rows.append([tok, 1, "MOUTH_CHECK", (dw + timedelta(minutes=2)).strftime("%Y-%m-%d %H:%M"), "", kit, "swallowed"])
        rows.append([tok, 1, "MEAL", (dw + timedelta(hours=4)).strftime("%Y-%m-%d %H:%M"), "", kit, "standard lunch"])
    rng.shuffle(rows)
    _G_write(data / "dose_admin_p1.csv", _G_csv_text(["subject", "period", "event", "local_time", "dose_mg", "kit", "comment"], rows))
    out = ['<?xml version="1.0" encoding="UTF-8"?>', f'<dosing study="{_GSTUDY}" period="2">']
    for s in W["subjects"]:
        if (s, 2) not in W["dose_wall"]:
            continue
        u = W["dose_utc"][(s, 2)]
        tok = st(s, (3, 4))
        kit = f"K-{W['form'][(s, 2)]}-{rng.randint(1000, 9999)}"
        for ev, dt in (("FAST_START", -10.0), ("DOSE", 0.0), ("MOUTH_CHECK", 2 / 60), ("MEAL", 4.0)):
            out.append(f'  <event subject="{tok}" type="{ev}" at="{_G_iso_off(u + timedelta(hours=dt))}" kit="{kit}"' + (f' mg="{_GDOSE_MG:g}"' if ev == "DOSE" else "") + "/>")
    out.append("</dosing>")
    _G_write(data / "dose_admin_p2.xml", "\n".join(out) + "\n")
    # draw-time logs with transcription errors and corrections
    corrections = []
    seq = 500
    wrong: dict[str, object] = {}
    collected = sorted(b for b, t in tubes.items() if t["status"] == "COLLECTED")
    err = rng.sample(collected, 70)
    for b in err:
        t = tubes[b]
        bad = t["wall"] + rng.choice([timedelta(hours=1), timedelta(hours=-1), timedelta(days=1), timedelta(minutes=30), timedelta(hours=10)])
        wrong[b] = bad
    missing = rng.sample([b for b in collected if b not in wrong and tubes[b]["nom"] not in (0, "UNS")], 4)
    for b in missing:
        wrong[b] = None
    W["no_time"] = set(missing[1:])
    for b in err + missing[:1]:
        t = tubes[b]
        if rng.random() < 0.3:
            seq += rng.randint(1, 4)
            decoy = t["wall"] + timedelta(minutes=rng.choice([-20, 15, 45]))
            corrections.append({"seq": seq, "tube": b, "field": "drawn_local", "value": decoy.strftime("%Y-%m-%d %H:%M"), "status": "POSTED"})
        seq += rng.randint(1, 4)
        corrections.append({"seq": seq, "tube": b, "field": "drawn_local", "value": t["wall"].strftime("%Y-%m-%d %H:%M"),
                            "status": rng.choice(["POSTED", "POSTED", "posted"])})
    for b in rng.sample(collected, 120):
        seq += rng.randint(1, 4)
        t = tubes[b]
        kind = rng.random()
        if kind < 0.45:
            corrections.append({"seq": seq, "tube": b, "field": "drawn_local", "value": (t["wall"] + timedelta(minutes=rng.choice([-60, 60, 90]))).strftime("%Y-%m-%d %H:%M"),
                                "status": rng.choice(["PENDING", "REVERSED", "draft"])})
        else:
            corrections.append({"seq": seq, "tube": b, "field": rng.choice(["phlebotomist", "comment", "arm"]), "value": rng.choice(["left", "JM", "re-drawn ok"]),
                                "status": "POSTED"})
    taken = set(err) | set(missing)
    chain_tubes = rng.sample([b for b in collected if b not in taken and tubes[b]["nom"] not in (0, "UNS")], _GCFG["reversal_chains"])
    W["chains"] = {}
    for i, b in enumerate(chain_tubes):
        t = tubes[b]
        kind = "ABCD"[i % 4]
        W["chains"][b] = kind
        bad = (t["wall"] + rng.choice([timedelta(hours=1), timedelta(minutes=-40), timedelta(minutes=50), timedelta(hours=2)])).strftime("%Y-%m-%d %H:%M")
        good = t["wall"].strftime("%Y-%m-%d %H:%M")
        if kind != "A":
            wrong[b] = t["wall"] + rng.choice([timedelta(hours=1), timedelta(hours=-1), timedelta(minutes=30)])

        def put(value: str, action: str | None, status: str = "POSTED", target: int | None = None) -> int:
            nonlocal seq
            seq += rng.randint(1, 4)
            e = {"seq": seq, "tube": b, "field": "drawn_local", "value": value, "status": status}
            if action is not None:
                e["action"] = action
            if target is not None:
                e["reverses"] = target
            corrections.append(e)
            return seq

        if kind == "A":
            s1 = put(bad, rng.choice(["SET", None]))
            put("", "REVERSE", target=s1)
        elif kind == "B":
            s1 = put(good, rng.choice(["SET", "set", None]))
            s2 = put("", "REVERSE", target=s1)
            put("", "REVERSE", target=s2)
        elif kind == "C":
            put(good, rng.choice(["SET", None]))
            s2 = put(bad, "SET")
            put("", "reverse", target=s2)
        else:
            s1 = put(good, None)
            put("", "REVERSE", status=rng.choice(["PENDING", "draft"]), target=s1)
    for c in corrections:
        if c["field"] == "drawn_local" and "action" not in c and rng.random() < 0.35:
            c["action"] = "SET"
    rng.shuffle(corrections)
    _G_write(data / "draw_time_corrections.ndjson", "".join(json.dumps(dict(c, tube=(c["tube"].lower() if rng.random() < 0.15 else c["tube"]),
                                                                          entered=_G_z(datetime(2026, 11, 11, tzinfo=_GUTC) + timedelta(minutes=c["seq"] * 7)))) + "\n"
                                                         for c in corrections))
    g1, g2 = [], []
    for b, t in sorted(tubes.items(), key=lambda kv: (kv[1]["subject"], kv[1]["period"], str(kv[1]["nom"]))):
        if t["status"] != "COLLECTED":
            continue
        val = wrong.get(b, t["wall"])
        if W["group"][t["subject"]] == "G1":
            g1.append([b, st(t["subject"], (0, 1, 2)), t["period"], _G_nom_txt(t["nom"]), "" if val is None else val.strftime("%Y-%m-%d %H:%M"),
                       rng.choice(["JM", "AK", "LP", "TS"]), ""])
        else:
            g2.append({"tube": b, "subj": st(t["subject"], (0, 2, 5)), "per": t["period"], "nom": _G_nom_txt(t["nom"]),
                       "drawn_at": None if val is None else _G_iso_off(_Gwall_to_utc(val)), "by": rng.choice(["JM", "AK", "LP", "TS"])})
    for _ in range(12):
        g1.append(list(rng.choice(g1)))
    _G_write(data / "draw_times_g1.tsv", _G_csv_text(["tube", "subject", "period", "nominal_h", "drawn_local", "phlebotomist", "comment"], g1, "\t"))
    _G_write(data / "draw_times_g2.jsonl", "".join(json.dumps(r) + "\n" for r in g2))
    # adverse events (background; designed emesis events are added once the analysis inputs are known)
    aes = []
    k = 1
    fill = ["Headache", "Dizziness", "Somnolence", "Back pain", "Catheter site pain", "Diarrhoea", "Fatigue", "Nausea", "Rhinitis", "Vessel puncture site bruise"]
    for _ in range(150):
        s = rng.choice(W["subjects"])
        p = rng.choice([q for q in (1, 2) if (s, q) in W["dose_wall"]])
        on = W["dose_wall"][(s, p)] + timedelta(hours=rng.uniform(0.2, 70))
        aes.append((f"AE{k:04d}", _GSTUDY, st(s, (4, 3, 0)), p, rng.choice(fill), "see narrative", on.strftime("%Y-%m-%d %H:%M"), rng.choice(["MILD", "MODERATE"]), "RESOLVED"))
        k += 1
    first_day = min(date.fromisoformat(v) for v in _GCFG["days"].values())
    for _ in range(80):
        n = rng.randint(1, 40)
        when = datetime.combine(first_day + timedelta(days=rng.randint(0, 17)), datetime.min.time()) + timedelta(hours=rng.randint(7, 20), minutes=rng.randint(0, 59))
        aes.append((f"FE{k:04d}", _GOTHER, f"S{n:03d}", rng.choice([1, 2, 3]), rng.choice(["Vomiting", "Headache", "Nausea", "Vomiting projectile"]), "other study",
                    when.strftime("%Y-%m-%d %H:%M"), "MILD", "RESOLVED"))
        k += 1
    W["ae_rows"] = aes
    W["ae_next"] = k
    W["st"] = st
    _G_write_ae_db(data, aes)
    # disposition event log
    rows = []
    for s in W["subjects"]:
        tok = st(s, (5, 0))
        rows.append([tok, "SCREENED", "", "2026-10-0" + str(rng.randint(1, 9)), ""])
        rows.append([tok, "RANDOMIZED", "", "2026-10-12", W["seq"][s]])
        for p in (1, 2):
            if (s, p) in W["dose_wall"]:
                rows.append([tok, "DOSED", str(p), W["dose_wall"][(s, p)].strftime("%Y-%m-%d"), ""])
        if s in _GDROPOUTS:
            wtok = _GSCR[s] if s == min(_GDROPOUTS) else tok
            rows.append([wtok, "WITHDRAWN", "1", W["dose_wall"][(s, 1)].strftime("%Y-%m-%d"), "consent withdrawn " + _GDROPOUTS[s]])
        elif s == _GMID_P2_WITHDRAW:
            rows.append([_GSCR[s], "WITHDRAWN", "2", W["dose_wall"][(s, 2)].strftime("%Y-%m-%d"), "left the unit 30 h after period 2 dose"])
        else:
            rows.append([tok, "COMPLETED", "2", "2026-11-12", ""])
            if rng.random() < 0.08:
                rows.append([tok, "FOLLOW_UP_CALL", "", "2026-11-20", "withdrawn from mailing list"])
    _G_write(data / "subject_disposition.psv", _G_csv_text(["subject", "event", "period", "event_date", "note"], rows, "|"))
    W["subj_tok"] = subj_tok


def _G_write_ae_db(data: Path, rows: list[tuple]) -> None:
    path = data / "ae_listing.db"
    if path.exists():
        path.unlink()
    con = sqlite3.connect(path)
    con.execute("create table ae_events (ae_id text, study text, subject text, period integer, pt text, verbatim text, onset_local text, severity text, outcome text)")
    con.executemany("insert into ae_events values (?,?,?,?,?,?,?,?,?)", rows)
    con.commit()
    con.close()


def _G_write_profile_calendar(rng: random.Random, W: dict, data: Path) -> None:
    out = ["# site calendar of the clinical research unit (wall clock = civil time at the unit)", f"site: {_GCFG['site']}", f"study: {_GSTUDY}",
           f"base_offset: \"+{_GBASE_OFFSET:02d}:00\"", "transitions:"]
    for when, o in _GTRANSITIONS:
        out += [f"  - at_utc: \"{_G_z(when)}\"", f"    offset_after: \"+{o:02d}:00\""]
    out += ["# daily civil offset at 12:00 local, informative", "days:"]
    days = [date.fromisoformat(v) for v in _GCFG["days"].values()]
    d = min(days) - timedelta(days=42)
    while d <= max(days) + timedelta(days=110):
        noon = _Gwall_to_utc(datetime.combine(d, datetime.min.time()) + timedelta(hours=12))
        out += [f"  - date: {d.isoformat()}", f"    offset_noon: \"+{_G_offset_at_utc(noon):02d}:00\"",
                f"    unit_open: {'yes' if d.weekday() < 6 else 'no'}"]
        d += timedelta(days=1)
    _G_write(data / "site_calendar.yml", "\n".join(out) + "\n")
    P = _GCFG["profile"]
    out = [f"# {_GSTUDY} analysis profile (statistics lead sign-off)", "# knobs below are the only source for these settings",
           f"study_id: {_GSTUDY}", f"nominal_sheet: {P['nominal_sheet']}", "analytes:"] + [f"  - {a}" for a in P["analytes"]]
    out += ["pivotal_analytes:"] + [f"  - {a}" for a in P["pivotal_analytes"]] + ["parameters:"] + [f"  - {x}" for x in P["parameters"]]
    for k in ("alpha", "be_lower_pct", "be_upper_pct", "lambda_z_min_points", "lambda_z_adj_r2_tolerance", "extrap_limit_pct",
              "carryover_limit_pct", "emesis_window_factor", "isr_limit_pct"):
        out.append(f"{k}: {P[k]}")
    scope = list(W["subjects"])
    if P["scope_drop"]:
        for s in rng.sample(scope, P["scope_drop"]):
            scope.remove(s)
    W["scope"] = set(scope)
    out += ["subjects_in_scope:"] + [f"  - {s}" for s in scope]
    out += ["# reviewers", "reviewers:", "  - name: statistics lead", "  - name: bioanalytical PI", "  - name: QA"]
    _G_write(data / "analysis_profile_be.yml", "\n".join(out) + "\n")


# --------------------------------------------------------------------------- references
def _G_write_refs(rng: random.Random, W: dict, data: Path) -> None:
    con = sqlite3.connect(data / "entity_alias_register.sqlite")
    con.execute("create table run_alias (token text, run_id text, source text)")
    con.execute("create table subject_alias (token text, subject_id text, study text)")
    rows = []
    for r in W["runs"]:
        for k in range(6):
            tok = _G_run_token(r["run_id"], k).strip()
            if k != 0 and tok.upper() != r["run_id"]:
                rows.append((tok if k != 1 else tok.upper(), r["run_id"], rng.choice(["LIMS", "MS export", "QA"])))
    for k in range(1, 21):
        rows.append((f"FE-R{k:03d}", f"FE-R{k:03d}", "other study"))
    rng.shuffle(rows)
    con.executemany("insert into run_alias values (?,?,?)", rows)
    srows = []
    for s in W["subjects"]:
        for k in range(1, 6):
            srows.append((_G_subj_token(s, k), s, _GSTUDY))
        srows.append((_GSCR[s], _G_subj_token(s, 3), _GSTUDY))
    for k in range(1, 41):
        srows.append((f"{_GOTHER}-{k:03d}", f"S{k:03d}", _GOTHER))
    for s in (_GMID_P2_WITHDRAW, _GRULED_OUT, min(_GDROPOUTS)):
        srows.append((_GSCR[s], f"{_GOTHER}-{rng.randint(1, 40):03d}", _GOTHER))
    rng.shuffle(srows)
    con.executemany("insert into subject_alias values (?,?,?)", srows)
    con.commit()
    con.close()
    con = sqlite3.connect(data / "integration_audit_trail.db")
    con.execute("create table audit_entry (entry_id text, injection_ref text, revision integer, action text, reason_code text, approver text, status text, ts text)")
    con.executemany("insert into audit_entry values (?,?,?,?,?,?,?,?)",
                    [(e["id"], e["inj"].lower() if rng.random() < 0.1 else e["inj"], e["rev"], "MANUAL_INTEGRATION" if e["rev"] > 1 else "REVIEW",
                      e["code"], rng.choice(["QA-1", "QA-2", "PI"]), e["status"] if rng.random() > 0.1 else e["status"].lower(), _G_z(e["ts"]))
                     for e in sorted(W["audit"], key=lambda e: e["id"])])
    con.commit()
    con.close()
    reqs = []
    for i, q in enumerate(W["std_requests"]):
        run = next(r for r in W["runs"] if r["run_id"] == q["run"])
        reqs.append({"request_id": f"SX-{i + 1:04d}", "run": _G_run_token(q["run"], rng.randint(0, 4)), "injection": q["inj"], "code": q["code"],
                     "status": q["status"], "requested_at": run["date"].isoformat() + "T16:00:00Z"})
    for i in range(140):
        run = rng.choice(W["runs"])
        reqs.append({"request_id": f"SX-{len(reqs) + 1:04d}", "run": _G_run_token(run["run_id"], rng.randint(0, 4)),
                     "injection": f"{run['run_id']}-I{rng.randint(3, 10):03d}" if rng.random() < 0.5 else f"{run['run_id']}-I{rng.randint(11, 60):03d}",
                     "code": rng.choice(["OUTLIER", "CURVE_FIT", "LOW_IS", "INJ_FAIL"]), "status": rng.choice(["REJECTED", "PENDING", "WITHDRAWN"]),
                     "requested_at": run["date"].isoformat() + "T17:00:00Z"})
    rng.shuffle(reqs)
    _G_write(data / "std_exclusion_requests.jsonl", "".join(json.dumps(r) + "\n" for r in reqs))
    rows = []
    inv = {v: k for k, v in W["newcode"].items()}
    for e in W["reassay_log"]:
        run = next(r for r in W["runs"] if r["run_id"] == e["run"])
        tube = e["tube"]
        tok = W["newcode"].get(tube, tube) if rng.random() < 0.3 else inv.get(tube, tube)
        reason = e["reason"]
        if reason == "ISR" and rng.random() < 0.3:
            reason = "REANALYSIS"
        elif reason == "RUN_FAIL" and rng.random() < 0.3:
            reason = "run fail"
        elif reason == "PK_REPEAT" and rng.random() < 0.4:
            reason = "pk-repeat"
        rows.append([tok, e["analyte"].lower() if rng.random() < 0.2 else e["analyte"], _G_run_token(e["run"], rng.randint(0, 4)), reason,
                     e["status"], e["requested"].isoformat(), run["analyst"]])
    for _ in range(45):
        e = rng.choice(W["reassay_log"])
        other = rng.choice([r for r in W["runs"] if r["analyte"] == e["analyte"] and r["run_id"] != e["run"]])
        rows.append([e["tube"], e["analyte"], other["run_id"], rng.choice(["ALQ", "PK_REPEAT", "RUN_FAIL"]), "CANCELLED", "2026-12-01", "QA"])
    rng.shuffle(rows)
    _G_write(data / "reassay_request_log.csv", _G_csv_text(["tube", "analyte", "run", "reason", "status", "requested_on", "requested_by"], rows))
    _G_write(data / "ingest_catalog_be.json", json.dumps({"study_id": _GSTUDY, "exported": "2026-12-20T07:30:00Z", "stream": "lcms_injections",
                                                        "shards": W["catalog"]}, indent=2) + "\n")


def _G_pad(rng: random.Random, v: float) -> object:
    return f" {v} " if rng.random() < 0.12 else v


def _G_write_workbook(rng: random.Random, W: dict, data: Path) -> None:
    lots = W["lots"]
    plan = [["Bioanalytical run plan", f"{_GSTUDY} and {_GOTHER}"], [], ["run_id", "study", "analyte", "run_type", "cal_lot", "qc_lot", "instrument",
                                                                     "analysis_date", "analyst", "comment"]]
    body = []
    for r in W["runs"]:
        rt = {"ORIG": "ORIGINAL", "REASSAY": "REASSAY", "ISR": "ISR"}[r["run_type"]]
        body.append([r["run_id"], _GSTUDY, r["analyte"] if rng.random() > 0.15 else r["analyte"].lower(), rt if rng.random() > 0.15 else rt.lower(),
                     r["cal_lot"], r["qc_lot"], r["instrument"], _G_serial(r["date"]), r["analyst"], ""])
    for k in range(1, 21):
        body.append([f"FE-R{k:03d}", _GOTHER, rng.choice(_GANALYTES), "ORIGINAL", "CS-V-2601", "QC-V-2601", "MS-02", _G_serial(date(2026, 11, 1) + timedelta(days=k)), "AKN", "food-effect study"])
    rng.shuffle(body)
    body.insert(len(body) // 2, ["note: rows below were re-keyed after the LIMS migration; lot columns verified against the CoA binder"])
    plan += body
    def cert_sheet(key: str) -> list[list[object]]:
        rows = [["lot", "analyte", "level", "target", "certified", "certified_on"]]
        for lot, v in lots["cal"].items():
            for i, lv in enumerate(_GLEVELS):
                rows.append([lot, v["analyte"], lv, _GTARGET[v["analyte"]][i], _G_pad(rng, v[key][i]), _G_serial(date(2026, 9, 1) + timedelta(days=int(lot[-1]) * 9))])
        return rows
    qc = [["lot", "analyte", "level", "target", "certified"]]
    for lot, v in lots["qc"].items():
        for lv, t in _GQC_TARGET[v["analyte"]].items():
            qc.append([lot, v["analyte"], lv, t, _G_pad(rng, v["values"][lv])])
    rand = [["Randomization list (final, unblinded at database lock)"], ["subject", "sequence", "group", "block", "randomized_on"]]
    for i, s in enumerate(W["subjects"]):
        rand.append([s, W["seq"][s] if rng.random() > 0.1 else W["seq"][s].lower(), W["group"][s], i // 4 + 1, _G_serial(date(2026, 10, 12))])
    draft = [["subject", "sequence", "group"]]
    swap = set(rng.sample(W["subjects"], 7))
    for s in W["subjects"]:
        q = W["seq"][s]
        draft.append([s, ("RT" if q == "TR" else "TR") if s in swap else q, W["group"][s]])
    notes = [["Workbook notes"], ["RunPlan is maintained by the bioanalytical PI; QC lots are certified by the reference-standard group."],
             ["CertNominal_2026R holds the re-certified values issued after the balance recalibration; the profile names the sheet in use."],
             ["CertNominal_DRAFT is an unapproved working copy."], ["Randomization_v0 is the pre-final list and was replaced."]]
    sheets = [("Notes", notes, False), ("RunPlan", plan, False), ("CertNominal_DRAFT", [["lot", "analyte", "level", "target", "certified"]] +
              [[lot, v["analyte"], lv, _GTARGET[v["analyte"]][i], v["draft"][i]] for lot, v in lots["cal"].items() for i, lv in enumerate(_GLEVELS)], True),
              ("CertNominal_2026", cert_sheet("values"), False), ("QCLots", qc, False), ("CertNominal_2026R", cert_sheet("recert"), False),
              ("Randomization_v0", draft, True), ("Randomization", rand, False)]
    order = list(range(1, len(sheets) + 1))
    rng.shuffle(order)
    _G_xlsx(data / "bioanalytical_workbook_v3.xlsx", sheets, order, rng)


_GEMESIS_TERMS = [("Vomiting", "Y"), ("Vomiting projectile", "Y"), ("Haematemesis", "Y"), ("Retching", "N"), ("Nausea", "N"), ("Regurgitation", "N"),
                ("Dyspepsia", "N"), ("Gastrooesophageal reflux", "N"), ("Abdominal discomfort", "N"), ("Hiccups", "N"), ("Vomiting psychogenic", "Y"),
                ("Cyclic vomiting syndrome", "N")]
_GC1 = [("BASELINE_DRIFT", "baseline drift under the peak", "Y"), ("SPLIT_PEAK", "peak split by the algorithm", "Y"), ("SHOULDER", "co-eluting shoulder", "Y"),
      ("NOISE_SPIKE", "noise spike in the window", "Y"), ("ANALYST_PREF", "analyst preference", "N"), ("MATCH_EXPECTED", "to match an expected value", "N"),
      ("PEAK_WIDTH", "peak width adjusted without cause", "N"), ("NONE", "no reason given", "N"), ("RT_SHIFT", "retention time shift", "Y"),
      ("TAILING", "excessive tailing", "Y"), ("SMOOTHING", "smoothing changed", "N"), ("INTEGRATION_EVENT", "integration event added", "N")]
_GC2 = [("INJ_FAIL", "injection failure documented by the instrument log", "Y"), ("PIPETTE_ERR", "pipetting error recorded at preparation", "Y"),
      ("VIAL_SWAP", "vial position swap", "Y"), ("LOW_IS", "low internal standard response", "N"), ("OUTLIER", "statistical outlier", "N"),
      ("CURVE_FIT", "improves the curve fit", "N"), ("SPIKE_ERR", "spiking solution error documented", "Y"), ("CARRYOVER", "carryover suspected", "N")]


def _G_rulings(rng: random.Random, W: dict) -> list[list[str]]:
    rows = []
    rid = 100

    def add(study: str, action: str, target: str, status: str, note: str) -> None:
        nonlocal rid
        rid += rng.randint(1, 3)
        rows.append([f"RL-{rid}", study, action, target, status, note])

    add(_GSTUDY, "EXCLUDE_SUBJECT", _GSCR[_GRULED_OUT], "IN FORCE", "prohibited concomitant medication (ibuprofen) on day -2")
    add(_GSTUDY, "EXCLUDE_SUBJECT", _G_subj_token(_GRULED_RESCINDED, 4), "RESCINDED", "suspected protocol deviation (later refuted)")
    for r in W["runs"]:
        if r["design"] == "ruling":
            add(_GSTUDY, "REJECT_RUN", _G_run_token(r["run_id"], 3), "IN FORCE", "internal standard response drift (QA memo 14)")
    other_runs = [r for r in W["runs"] if r["design"] is None and r["run_type"] == "ORIG"]
    for r in rng.sample(other_runs, 2):
        add(_GSTUDY, "REJECT_RUN", _G_run_token(r["run_id"], 0), "RESCINDED", "IS drift suspected (retracted after trend review)")
    collected = sorted(b for b, t in W["tubes"].items() if t["status"] == "COLLECTED" and t["nom"] != "UNS")
    picks = rng.sample(collected, 40)
    W["excl_samples"] = set(picks[:30])
    for i, b in enumerate(picks):
        tok = W["newcode"].get(b, b) if rng.random() < 0.4 else b
        tok = tok.lower() if rng.random() < 0.2 else tok
        add(_GSTUDY, "EXCLUDE_SAMPLE", tok, "IN FORCE" if i < 30 else "RESCINDED",
            rng.choice(["haemolysed (grade 3)", "tube leaked in transit", "label mismatch (resolved)", "thawed > 2 h"]))
    for k in range(150):
        act = rng.choice(["EXCLUDE_SAMPLE", "EXCLUDE_SUBJECT", "REJECT_RUN"])
        tgt = {"EXCLUDE_SAMPLE": f"FB{rng.randint(100000, 999999)}", "EXCLUDE_SUBJECT": f"S{rng.randint(1, 40):03d}", "REJECT_RUN": f"FE-R{rng.randint(1, 20):03d}"}[act]
        add(_GOTHER, act, tgt, rng.choice(["IN FORCE", "IN FORCE", "RESCINDED"]), "food-effect study ruling")
    rng.shuffle(rows)
    return rows


def _G_write_memo(rng: random.Random, W: dict, data: Path) -> None:
    pages: list[list[list[str]]] = []
    cur: list[list[str]] = [["Bioanalysis and statistics governance memo"], [f"Study {_GSTUDY} (veraxolol 40 mg, two-way crossover)"],
                            ["Issued by the clinical pharmacology governance board, 2026-12-19."],
                            ["Tables marked IN FORCE govern the analysis. Tables marked WITHDRAWN are kept for audit only."],
                            ["Table P-0 below is the pre-amendment convention set and must not be applied."]]

    def emit(title: str, header: list[str], rows: list[list[str]], per_page: int = 70) -> None:
        nonlocal cur
        block = [[title], header] + rows
        if len(cur) + 2 > per_page:
            pages.append(cur)
            cur = []
        room = per_page - len(cur)
        cur += block[:room]
        rest = block[room:]
        tid = title.split(":")[0]
        while rest:
            pages.append(cur)
            cur = [[f"{tid} (continued)"], header] + rest[:per_page - 2]
            rest = rest[per_page - 2:]

    p0 = [["time_base", "nominal", "scheduled hours"], ["auc_method", "linear", "linear trapezoid throughout"], ["blq_before_first_quantifiable", "half LLOQ", ""],
          ["blq_after_first_quantifiable", "half LLOQ", ""], ["lambda_z_selection", "last 3 points", "fixed"], ["aucinf_clast", "observed", ""],
          ["potency_correction", "applied", "assay content of the batch"], ["ci_rounding", "1 decimal", ""], ["decision_basis", "unrounded bounds", ""],
          ["unscheduled_samples", "included", ""], ["isr_acceptance", "67 % within limit", ""], ["emesis_reference", "median Tmax", "all formulations, computed once"]]
    p1 = [["time_base", "actual", "elapsed hours from the dose instant to the draw instant"],
          ["auc_method", "linear-up/log-down", "log trapezoid where the concentration falls and both ends are positive"],
          ["blq_before_first_quantifiable", "zero", "pre-dose included"], ["blq_after_first_quantifiable", "excluded", "embedded and trailing"],
          ["lambda_z_selection", "adjusted R-squared best fit", "see handbook H15"], ["aucinf_clast", "predicted", "Clast from the terminal regression (amendment A2)"],
          ["potency_correction", "none", ""], ["ci_rounding", "2 decimals", "half away from zero, on percentages"], ["decision_basis", "rounded bounds", ""],
          ["unscheduled_samples", "excluded from NCA", ""], ["isr_acceptance", "two thirds within limit", "pairs with |diff| at or below isr_limit_pct"],
          ["emesis_reference", "mean Tmax", "reference formulation, first pivotal analyte, passes per handbook H16"],
          ["concentration_rounding", "4 significant digits", "half away from zero, before any use (handbook H22)"],
          ["elapsed_time_rounding", "4 decimals", "hours, half away from zero, before any use (handbook H22)"]]
    emit("Table P-0: Analysis conventions [WITHDRAWN]", ["parameter", "value", "note"], p0)
    cur.append(["Table P-1 replaces Table P-0 from amendment A2 onward."])
    emit("Table P-1: Analysis conventions [IN FORCE]", ["parameter", "value", "note"], p1)
    mh = ["analyte", "model", "weighting", "std_limit_pct", "lloq_std_limit_pct", "qc_limit_pct", "dqc_limit_pct", "min_std_fraction", "min_levels",
          "min_qc_fraction", "min_qc_level_fraction", "unit"]
    emit("Table M-1: Bioanalytical method parameters [WITHDRAWN]", mh,
         [["VRX", "linear", "1/x", "15", "20", "15", "15", "0.75", "6", "0.67", "none", "ng/mL"], ["M1", "linear", "1/x^2", "15", "20", "15", "15", "0.75", "6", "0.67", "none", "ng/mL"]])
    emit("Table M-2: Bioanalytical method parameters [IN FORCE]", mh, [[a] + list(_GCFG["m2"][a]) + ["ng/mL"] for a in _GANALYTES])
    emit("Table C-1: Manual integration reason codes [IN FORCE]", ["code", "description", "allowed"], [list(x) for x in _GC1])
    emit("Table C-2: Assignable causes for calibration standard exclusion [IN FORCE]", ["code", "description", "allowed"], [list(x) for x in _GC2])
    emit("Table E-1: Emesis preferred terms [IN FORCE]", ["preferred_term", "counts_as_emesis"], [list(x) for x in _GEMESIS_TERMS])
    emit("Table T-0: Standard normal quantiles [REFERENCE ONLY]", ["p", "z"], [[f"{p:.3f}", f"{_G_zq(p):.6f}"] for p in (0.8, 0.85, 0.9, 0.95, 0.975, 0.99, 0.995)])
    tt = [[str(df), f"{_Gtq(0.90, df):.6f}", f"{_Gtq(0.95, df):.6f}", f"{_Gtq(0.975, df):.6f}"] for df in range(1, 201)]
    emit("Table T-1: Student t quantiles (one-sided lower-tail probability p) [IN FORCE]", ["df", "p=0.90", "p=0.95", "p=0.975"], tt)
    emit("Table R-1: Rulings", ["ruling_id", "study", "action", "target", "status", "note"], _G_rulings(rng, W))
    emit("Table S-1: SAP amendments", ["amendment", "date", "change", "status"],
         [["A1", "2026-09-30", "draft SAP v1 (observed Clast, nominal times)", "SUPERSEDED"], ["A2", "2026-11-28", "predicted Clast for AUCinf; actual times; Table P-1", "IN FORCE"],
          ["A3", "2026-12-15", "emesis rule uses the mean reference Tmax", "IN FORCE"], ["A4", "2026-12-18", "potency correction proposal (rejected)", "REJECTED"],
          ["A5", "2026-12-19", "emesis window iterated over passes; rounding cadence (handbook revision 5)", "IN FORCE"]])
    cur.append(["End of memo. Questions to the governance board secretariat (room 2.14)."])
    pages.append(cur)
    _G_pdf(data / "ba_stat_governance_memo.pdf", pages, rng)


