def _G_ols(xs: list[float], ys: list[float]) -> tuple[float, float]:
    n = len(xs)
    mx, my = sum(xs) / n, sum(ys) / n
    sxx = sum((x - mx) ** 2 for x in xs)
    b = sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / sxx
    return my - b * mx, b


def _G_write_published(rng: random.Random, W: dict, data: Path) -> None:  # noqa: C901
    tubes = W["tubes"]
    runs = {r["run_id"]: r for r in W["runs"]}
    best: dict[tuple, tuple] = {}
    for row in W["lims"]:
        run = runs[row["run"]]
        if row["run_status"] != "ACCEPTED" or row["flag"] == "DQC_FAIL":
            continue
        key = (row["tube"], row["analyte"])
        k = (run["date"], row["run"], row["seq"])
        if key not in best or k > best[key][0]:
            best[key] = (k, row)
    prof: dict[tuple, list] = {}
    for (tube, a), (_, row) in best.items():
        t = tubes[tube]
        if t["nom"] == "UNS":
            continue
        val = row["conc"] if row["flag"] == "OK" else (_GTARGET[a][0] / 2 if row["flag"] == "BLQ" else None)
        if val is None:
            continue
        prof.setdefault((t["subject"], t["period"], a), []).append((float(t["nom"]), val))
    pub = {}
    rows = []
    for (s, p, a) in sorted(prof):
        pts = sorted(prof[(s, p, a)])
        cmax = max(v for _, v in pts)
        tmax = next(t for t, v in pts if v == cmax)
        auc = sum((t2 - t1) * (v1 + v2) / 2 for (t1, v1), (t2, v2) in zip(pts, pts[1:]))
        lz = None
        tail = pts[-3:]
        if len(pts) >= 4 and all(v > 0 for _, v in tail):
            _, b = _G_ols([t for t, _ in tail], [math.log(v) for _, v in tail])
            lz = -b if b < 0 else None
        aucinf = auc + pts[-1][1] / lz if lz else None
        pub[(s, p, a)] = {"Cmax": cmax, "AUClast": auc, "AUCinf": aucinf}
        rows.append([s, p, W["form"][(s, p)], a, f"{cmax:.3f}", f"{tmax:g}", f"{auc:.3f}", "" if aucinf is None else f"{aucinf:.3f}",
                     "" if lz is None else f"{lz:.5f}", "" if lz is None else f"{math.log(2) / lz:.3f}"])
    _G_write(data / "be_report_published.csv", _G_csv_text(["subject", "period", "formulation", "analyte", "cmax", "tmax", "auc_last", "auc_inf", "lambda_z", "half_life"], rows))
    W["published"] = pub
    stats = {"study": _GSTUDY, "method": "paired t on log(T) - log(R), potency corrected, t(0.975, n-1)", "generated": "2026-12-08T10:00:00Z", "results": []}
    for a in _GANALYTES:
        for prm in ("Cmax", "AUClast", "AUCinf"):
            d = []
            for s in W["subjects"]:
                v1, v2 = pub.get((s, 1, a), {}).get(prm), pub.get((s, 2, a), {}).get(prm)
                if v1 is None or v2 is None:
                    continue
                tv, rv = (v1, v2) if W["form"][(s, 1)] == "T" else (v2, v1)
                d.append(math.log(tv * 100 / _GPOTENCY["T"]) - math.log(rv * 100 / _GPOTENCY["R"]))
            n = len(d)
            m = sum(d) / n
            sd = math.sqrt(sum((x - m) ** 2 for x in d) / (n - 1))
            t = float(f"{_Gtq(0.975, n - 1):.3f}")
            lo, hi = 100 * math.exp(m - t * sd / math.sqrt(n)), 100 * math.exp(m + t * sd / math.sqrt(n))
            stats["results"].append({"analyte": a, "parameter": prm, "n": n, "ratio_pct": round(100 * math.exp(m), 2), "ci_lower_pct": round(lo, 2),
                                     "ci_upper_pct": round(hi, 2), "result": "PASS" if lo >= 80 and hi <= 125 else "FAIL"})
    _G_write(data / "be_statistics_published.json", json.dumps(stats, indent=2) + "\n")
    # LIMS cache
    lines = []
    for row in W["lims"]:
        key = (row["tube"], row["analyte"])
        rep = key in best and best[key][1] is row
        lines.append(json.dumps({"run": row["run"], "tube": row["tube"], "analyte": row["analyte"], "conc_ng_ml": row["conc"], "flag": row["flag"],
                                 "run_status": row["run_status"], "reason": row["reason"], "reportable": rep}))
    _G_write(data / "lims_concentration_cache.jsonl", "\n".join(lines) + "\n")
    rows = []
    for r in sorted(W["runs"], key=lambda r: r["run_id"]):
        rows.append([r["run_id"], r["analyte"], r["lab"]["status"], f"{r['lab']['qc_pct']:.1f}", f"{r['lab']['std_pct']:.1f}", r["analyst"],
                     "rejected by ruling" if r["ruling"] else ""])
    _G_write(data / "run_status_dashboard.csv", _G_csv_text(["run_id", "analyte", "lab_status", "qc_pass_pct", "std_retained_pct", "reviewed_by", "comment"], rows))
    # quick reference with two-sided 95 % values
    out = ["STATISTICS QUICK REFERENCE (training handout, 2019)", "", "Normal: z(0.95) = 1.645, z(0.975) = 1.960", "",
           "Two-sided 95 % critical values of Student t (use for confidence intervals):", "df    t"]
    out += [f"{df:<5d} {_Gtq(0.975, df):.3f}" for df in range(1, 121)]
    out += ["", "Equivalence: compare the CI with 80-125 %.", "Paired designs: analyse within-subject differences T - R."]
    _G_write(data / "stat_quick_reference.txt", "\n".join(out) + "\n")
    # bulletin
    out = ["BIOANALYTICAL LAB BULLETIN - November 2026", "",
           "* Run acceptance (lab SOP BA-021 rev 3): QC pass rate must reach 67 % and more than 75 % of calibrators must be retained.",
           "* VRX curves: linear, 1/x weighting (method validation report MVR-0611). M1 curves: linear, 1/x^2.",
           "* Use the target calibrator concentrations printed on the method sheet; lot certificates are filed separately.",
           "* Out-of-limit calibrators are removed in one pass and the curve refitted once.",
           "* Reported concentration = most recent accepted result for the tube (reassays and ISR overwrite older values).",
           "* PK team note: nominal sampling times are accurate enough for NCA; clock changes do not matter for elapsed hours.",
           "* Potency: correct test and reference results to label claim using the certificates of analysis.",
           "* Statistics: paired comparison of T and R per subject, 95 % t interval.",
           "* Emesis: window = twice the median Tmax of all evaluable profiles, worked out once before any exclusion.",
           "* Keep concentrations and sampling times unrounded all the way through NCA; round only the final tables.",
           "* Correction journal: apply every POSTED drawn_local line in seq order; REVERSE lines are notes for QA.",
           "* Screening numbers (SCR-) are listed in the alias register next to the subject number they were given.", "", "Run digest (lab view):"]
    for r in sorted(W["runs"], key=lambda r: (r["date"], r["run_id"])):
        out.append(f"{r['date'].isoformat()}  {r['run_id']:<9} {r['analyte']:<4} {r['run_type']:<8} lab={r['lab']['status']:<9} qc={r['lab']['qc_pct']:.1f}% std={r['lab']['std_pct']:.1f}%")
    for k in range(130):
        out.append(f"instrument log: MS-0{k % 4 + 1} source cleaned {2026}-11-{(k % 28) + 1:02d}, tune file T{k:03d} loaded")
    _G_write(data / "lab_bulletin_nov.txt", "\n".join(out) + "\n")
    # legacy method sheet
    out = ["# legacy method sheet (method validation 2025)", "methods:"]
