        out += [f"  - run: MV-{a}-{k // 2 + 1:02d}", f"    slope: {0.0118 * (1 + rng.gauss(0, 0.05)):.6f}", f"    intercept: {0.0006 * (1 + rng.gauss(0, 0.3)):.6f}"]
