def _seal(root: Path) -> None:
    for p in root.iterdir():
        p.chmod(0o644)
    root.chmod(0o755)
    root.parent.chmod(0o755)


def _shipped() -> Path:
    with _LOCK:
        if "shipped" not in _MEMO:
            root = Path(tempfile.mkdtemp(prefix="be-shipped-")) / "data"
            root.mkdir()
            for rel, blob in _SHIPPED_DATA.items():
                (root / rel).write_bytes(zlib.decompress(base64.b64decode(blob)))
            _seal(root)
            _MEMO["shipped"] = root
        return _MEMO["shipped"]


def _fresh(tag: str) -> Path:
    base = Path(tempfile.mkdtemp(prefix=f"be-{tag}-"))
    base.chmod(0o755)
    return base / "data"


def _clone(dst: Path) -> Path:
    shutil.copytree(_shipped(), dst)
    _seal(dst)
    return dst


def _to_wall(u: datetime, root: Path) -> str:
    cal = _yaml((root / "site_calendar.yml").read_text(encoding="utf-8"))
    off = _mins(cal["base_offset"])
    for t in sorted(cal["transitions"], key=lambda t: t["at_utc"]):
        if u >= datetime.fromisoformat(t["at_utc"].replace("Z", "+00:00")):
            off = _mins(t["offset_after"])
    return (u + timedelta(minutes=off)).strftime("%Y-%m-%d %H:%M")


def _m_corrections(root: Path) -> None:
    """Append SET and REVERSE chains (and reversals of shipped corrections) to the correction journal."""
    rng = random.Random(SHIPPED_SEED ^ 0xC0EC)
    S = _st(_shipped())
    path = root / "draw_time_corrections.ndjson"
    old = [json.loads(x) for x in path.read_text(encoding="utf-8").split("\n") if x.strip()]
    seq = max(int(o["seq"]) for o in old) + 10
    shipped_sets: dict[str, int] = {}
    for o in old:
        if _k(o["status"]) == "POSTED" and o["field"] == "drawn_local" and (_k(o.get("action")) or "SET") == "SET":
            t = _k(o["tube"])
            shipped_sets[t] = max(shipped_sets.get(t, 0), int(o["seq"]))
    pool = sorted(t for t, tb in S["TUBE"].items() if tb[3] and tb[2] not in (None, 0.0) and S["DRAWU"].get(t) and tb[0] in S["SCOPE"])
    picks = rng.sample([t for t in pool if t not in shipped_sets], 26) + rng.sample(sorted(t for t in shipped_sets if t in pool), 4)
    lines = []

    def put(tube: str, value: str, action: str | None, status: str = "POSTED", target: int | None = None) -> int:
        nonlocal seq
        seq += rng.randint(1, 3)
        e = {"seq": seq, "tube": tube if rng.random() < 0.8 else tube.lower(), "field": "drawn_local", "value": value, "status": status}
        if action is not None:
            e["action"] = action
        if target is not None:
            e["reverses"] = target
        e["entered"] = "2027-01-05T09:00:00Z"
        lines.append(e)
        return seq

    for i, t in enumerate(picks):
        u = S["DRAWU"][t]
        shifted = (lambda m: _to_wall(u + timedelta(minutes=m), root))
        kind = i % 5 if i < 26 else 5
        if kind == 0:
            put(t, shifted(rng.choice([17, -23, 41])), rng.choice(["SET", None]))
        elif kind == 1:
            put(t, shifted(15), "SET")
            s2 = put(t, shifted(70), None)
            put(t, "", "REVERSE", target=s2)
        elif kind == 2:
            s1 = put(t, shifted(-12), "set")
            s2 = put(t, "", "REVERSE", target=s1)
            put(t, "", "Reverse", target=s2)
        elif kind == 3:
            s1 = put(t, shifted(33), None)
            put(t, "", "REVERSE", status="PENDING", target=s1)
        elif kind == 4:
            put(t, shifted(-35), "SET", status="posted")
        else:
            put(t, "", "REVERSE", target=shipped_sets[t])
    rng.shuffle(lines)
    path.write_text(path.read_text(encoding="utf-8") + "".join(json.dumps(x) + "\n" for x in lines), encoding="utf-8")


def _m_profile(root: Path) -> None:
    """Change the governing profile knobs, analyte and parameter order and the subject scope of the shipped corpus."""
    rng = random.Random(SHIPPED_SEED ^ 0x9F0F)
    p = root / "analysis_profile_be.yml"
    P = _yaml(p.read_text(encoding="utf-8"))
    scope = list(P["subjects_in_scope"])
    for s in rng.sample(scope, 4):
        scope.remove(s)
    out = [f"study_id: {P['study_id']}", "nominal_sheet: CertNominal_2026R", "analytes:", "  - M1", "  - VRX", "pivotal_analytes:", "  - VRX", "  - M1",
           "parameters:", "  - Cmax", "  - AUCinf", "  - AUClast", 'alpha: "0.10"', 'be_lower_pct: "90.00"', 'be_upper_pct: "111.11"',
           "lambda_z_min_points: 4", 'lambda_z_adj_r2_tolerance: "0.001"', 'extrap_limit_pct: "25"', 'carryover_limit_pct: "2"',
           'emesis_window_factor: "2.5"', 'isr_limit_pct: "15"', "subjects_in_scope:"] + [f"  - {s}" for s in scope]
    p.write_text("\n".join(out) + "\n", encoding="utf-8")


def _held_out(name: str) -> Path:
    with _LOCK:
        k = "corpus:" + name
        if k not in _MEMO:
            root = _fresh(name)
            if name in HELD:
                seed, cfg = HELD[name]
                _Ggenerate(root, seed, cfg)
            else:
                _clone(root)
                {"m_corrections": _m_corrections, "m_profile": _m_profile}[name](root)
            _seal(root)
            _MEMO[k] = root
        return _MEMO[k]


def _renamed() -> Path:
    with _LOCK:
        if "corpus:renamed" not in _MEMO:
            root = _clone(_fresh("renamed"))
            cat_path = root / "ingest_catalog_be.json"
            cat = json.loads(cat_path.read_text(encoding="utf-8"))
            for i, sh in enumerate(cat["shards"]):
                stem, ext = sh["file"].rsplit(".", 1)
                new = f"zq{i:02d}_{stem[::-1]}.{ext}"
                (root / sh["file"]).rename(root / new)
                sh["file"] = new
            cat_path.write_text(json.dumps(cat, indent=2) + "\n", encoding="utf-8")
            _seal(root)
            _MEMO["corpus:renamed"] = root
        return _MEMO["corpus:renamed"]


def _root_only_tests_present() -> bool:
    try:
        status = Path("/tests").stat()
    except FileNotFoundError:
        return False
    return status.st_uid == 0 and (status.st_mode & 0o077) == 0


def _untrusted(command: list[str]) -> list[str]:
    if os.name == "posix" and os.geteuid() != 0 and _root_only_tests_present():
        raise RuntimeError("verifier must run as root to isolate submitted code from /tests")
    if os.name == "posix" and os.geteuid() == 0:
        return [*_SETPRIV, *command]
    return command


def _staged_program() -> Path | None:
    """Copy the delivered program into a verifier-owned directory, readable by the unprivileged runner."""
    with _LOCK:
        if "staged" not in _MEMO:
            _MEMO["staged"] = None
            if PROGRAM.is_file():
                stage = Path(tempfile.mkdtemp(prefix="be-prog-"))
                stage.chmod(0o755)
                staged = stage / "run_be.py"
                shutil.copyfile(PROGRAM, staged)
                staged.chmod(0o755)
                _MEMO["staged"] = staged
        return _MEMO["staged"]


def _run(root: Path, tag: str) -> Path | None:
    with _LOCK:
        k = "run:" + tag
        if k in _MEMO:
            return _MEMO[k]
        _MEMO[k] = None
        prog = _staged_program()
        if prog is None:
            return None
        prog.chmod(0o755)
        work = Path(tempfile.mkdtemp(prefix=f"be-run-{tag}-"))
        work.chmod(0o777)
        out = work / "out"
        try:
            proc = subprocess.Popen(_untrusted([sys.executable, str(prog), str(root), str(out)]), stdout=subprocess.DEVNULL,
                                    stderr=subprocess.DEVNULL, start_new_session=True)
            try:
                code = proc.wait(timeout=240)
            except subprocess.TimeoutExpired:
                code = -1
            finally:
                try:
                    os.killpg(proc.pid, 9)
                except OSError:
                    pass
                proc.wait()
            if code == 0 and out.is_dir():
                _MEMO[k] = out
        except (OSError, subprocess.SubprocessError):
            _MEMO[k] = None
        return _MEMO[k]


def _mine(name: str) -> str | None:
    try:
        return (OUT / name).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None


def _out_text(out: Path | None, name: str) -> str | None:
    if out is None:
        return None
    try:
        return (out / name).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None


def _exact(name: str) -> bool:
    got = _mine(name)
    return got is not None and _same(name, got, derive(_shipped())[name])


def _core_exact(out: Path | None, root: Path) -> bool:
    if out is None:
        return False
    want = derive(root)
    for n in CORE:
        got = _out_text(out, n)
        if got is None or not _same(n, got, want[n]):
            return False
    return True


def _full_core() -> bool:
    """The spine: every core report is exact in /app/out for the shipped corpus and in the rerun on every held-out corpus."""
    with _LOCK:
        if "full_core" not in _MEMO:
            _MEMO["full_core"] = all(_exact(n) for n in CORE) and all(_core_exact(_run(_held_out(n), n), _held_out(n)) for n in HELD_OUT)
        return _MEMO["full_core"]


def _all_exact(out: Path | None, root: Path) -> bool:
    if out is None:
        return False
    want = derive(root)
    for n in NAMES:
        got = _out_text(out, n)
        if got is None or not _same(n, got, want[n]):
            return False
    return True


def _held_out_exact(name: str) -> bool:
    if not _full_core():
        return False
    root = _held_out(name)
    return _all_exact(_run(root, name), root)


def _leaf(*names: str) -> bool:
    return _full_core() and all(_exact(n) for n in names)


def _matches_flip(flip: str, name: str) -> bool:
    """True when the delivered report equals the named wrong reading and that reading differs from the truth."""
    got = _mine(name)
    want = derive(_shipped())[name]
    alt = derive(_shipped(), flip)[name]
    return got is not None and not _same(name, alt, want, True) and _same(name, got, alt)


def _sources() -> str:
    try:
        return "\n".join(p.read_text(encoding="utf-8", errors="replace") for p in sorted(OUT.glob("*.py")))
    except OSError:
        return ""


def _safe(fn) -> bool:
    try:
        return bool(fn())
    except Exception:
        return False


def _csv_rows(name: str) -> list[dict[str, str]]:
    text = _mine(name) or ""
    sep = {".csv": ",", ".tsv": "\t", ".psv": "|"}[Path(name).suffix]
    return _rows(text, sep)


