# =========================================================================== negative checks (True when the cheat or wrong reading is present)
def _echoes_shipped() -> bool:
    root = _held_out("h_reseed")
    want_v = derive(root)["reported_concentrations.csv"]
    want_s = derive(_shipped())["reported_concentrations.csv"]
    if _same("reported_concentrations.csv", want_v, want_s, True):
        return False
    got = _out_text(_run(root, "h_reseed"), "reported_concentrations.csv")
    return got is not None and _same("reported_concentrations.csv", got, want_s)


@criterion(description="The program ignores its input and replays the shipped reported concentrations on a held-out corpus")
def negative_hardcoded_sample_answers(workspace: Path) -> bool:
    # inverted: True only when the held-out rerun reproduces the shipped answer although its truth differs
    return _safe(_echoes_shipped)


@criterion(description="The program is exact on a copy of the shipped corpus and wrong once only the shard file names change")
def negative_filename_dependent_behaviour(workspace: Path) -> bool:
    # inverted: True only when renaming shards (and their catalog entries) alone breaks an otherwise exact program
    def chk() -> bool:
        if _echoes_shipped():
            return False
        if not _all_exact(_run(_clone(_fresh("copy")), "copy"), _shipped()):
            return False
        return not _all_exact(_run(_renamed(), "renamed"), _renamed())
    return _safe(chk)


@criterion(description="Two runs of the program on copies of the same corpus write different report bytes")
def negative_nondeterministic_output(workspace: Path) -> bool:
    # inverted: True only when two complete runs disagree on at least one report
    def chk() -> bool:
        a = _run(_clone(_fresh("copy")), "copy")
        b = _run(_clone(_fresh("copy2")), "copy2")
        if a is None or b is None:
            return False
        return any(_out_text(a, n) != _out_text(b, n) for n in NAMES)
    return _safe(chk)


@criterion(description="The delivered source refers to verifier paths or grading files")
def negative_touches_grader(workspace: Path) -> bool:
    # inverted: True when the program names the grader's files
    src = _sources().lower()
    return any(t in src for t in ("/tests/", "test_output", "judge.toml", "rewardkit"))


@criterion(description="The delivered source imports a third-party or network package")
def negative_third_party_or_network(workspace: Path) -> bool:
    # inverted: True when a banned import is present
    def chk() -> bool:
        banned = {"requests", "urllib3", "httpx", "socket", "pandas", "numpy", "openpyxl", "pypdf", "PyPDF2", "yaml", "xlrd", "fitz", "pdfplumber",
                  "lxml", "pdfminer", "scipy", "statsmodels", "polars", "duckdb", "pingouin"}
        for p in sorted(OUT.glob("*.py")):
            for node in ast.walk(ast.parse(p.read_text(encoding="utf-8"))):
                names = ({a.name.split(".")[0] for a in node.names} if isinstance(node, ast.Import) else
                         {(node.module or "").split(".")[0]} if isinstance(node, ast.ImportFrom) else set())
                if names & banned:
                    return True
        return False
    try:
        return _safe(chk)
    except Exception:
        return False


@criterion(description="nca_parameters.csv repeats the Cmax or AUClast of the faulty published report for at least half of the profiles")
def negative_echoes_published(workspace: Path) -> bool:
    # inverted: True when the published values are copied
    def chk() -> bool:
        pub = {(_k(r["subject"]), r["period"], _k(r["analyte"])): r for r in _rows((_shipped() / "be_report_published.csv").read_text(encoding="utf-8"), ",")}
        hit = tot = 0
        for r in _csv_rows("nca_parameters.csv"):
            p = pub.get((_k(r["subject_id"]), r["period"], _k(r["analyte"])))
            if p and r.get("cmax") and p["cmax"]:
                tot += 1
                hit += (_DEC.match(r["cmax"].strip()) and Decimal(r["cmax"].strip()) == Decimal(p["cmax"])) or \
                       (bool(r.get("auc_last")) and _DEC.match(r["auc_last"].strip()) is not None and Decimal(r["auc_last"].strip()) == Decimal(p["auc_last"]))
        return tot >= 50 and hit * 2 >= tot
    try:
        return _safe(chk)
    except Exception:
        return False


@criterion(description="calibration_fits.json applies the withdrawn Table M-1 VRX weighting or a linear M1 model for at least half of the runs")
def negative_withdrawn_curve_model(workspace: Path) -> bool:
    # inverted: True when the withdrawn method table drives the fits
    def chk() -> bool:
        runs = json.loads(_mine("calibration_fits.json") or "{}").get("runs", [])
        bad = [r for r in runs if (r.get("analyte") == "VRX" and str(r.get("weighting")).replace(" ", "") in ("1/x", "1", "none", ""))
               or (r.get("analyte") == "M1" and (str(r.get("model")).lower() == "linear" or (r.get("coefficients") or {}).get("c") in (None, 0, 0.0)))]
        return len(runs) >= 20 and len(bad) * 2 >= len(runs)
    try:
        return _safe(chk)
    except Exception:
        return False


@criterion(description="nca_parameters.csv AUClast follows the linear trapezoid on falling segments for at least sixty percent of the profiles")
def negative_linear_trapezoid(workspace: Path) -> bool:
    # inverted: True when the linear rule replaced the log-down rule
    def chk() -> bool:
        S = _st(_shipped())
        lin = {}
        for (s, per, an), R in S["NCA"].items():
            if "pts" in R:
                pts = R["pts"]
                lin[(s, str(per), an)] = sum((t2 - t1) * (c1 + c2) / 2 for (t1, c1), (t2, c2) in zip(pts, pts[1:]))
        hit = tot = 0
        for r in _csv_rows("nca_parameters.csv"):
            k = (r["subject_id"], r["period"], r["analyte"])
            if k in lin and r.get("auc_last"):
                tot += 1
                hit += _cell_ok(r["auc_last"], repr(lin[k]))
        return tot >= 50 and hit * 5 >= tot * 3
    return _safe(chk)


@criterion(description="be_statistics.json reports a paired-difference or two-sided 95 percent t interval for the pivotal Cmax")
def negative_wrong_interval_method(workspace: Path) -> bool:
    # inverted: True when the published interval method is reproduced
    def chk() -> bool:
        S = _st(_shipped())
        an = S["PIV"][0]
        v = S["BE"]["analytes"][an]["parameters"]["Cmax"]
        got = json.loads(_mine("be_statistics.json") or "{}")["analytes"][an]["parameters"]["Cmax"]
        lo = float(got["ci_lower_pct"])
        if abs(lo - v["ci_lower_pct"]) <= 0.006:
            return False
        df = v["df"]
        alts = [math.exp(v["estimate_log"] - _f(S["tt"][df]["p=0.975"]) * v["se_log"]) * 100]
        d = []
        for s in sorted(S["SEQ"]):
            if not S["POP"][(s, an, "Cmax")]:
                y1, y2 = math.log(S["NCA"][(s, 1, an)]["cmax"]), math.log(S["NCA"][(s, 2, an)]["cmax"])
                d.append(y1 - y2 if S["SEQ"][s] == "TR" else y2 - y1)
        m = sum(d) / len(d)
        sd = math.sqrt(sum((x - m) ** 2 for x in d) / (len(d) - 1))
        for col in ("p=0.95", "p=0.975"):
            alts.append(math.exp(m - _f(S["tt"][len(d) - 1][col]) * sd / math.sqrt(len(d))) * 100)
        alts.append(math.exp(m - 1.645 * sd / math.sqrt(len(d))) * 100)
        return any(abs(lo - a) <= 0.006 for a in alts)
    try:
        return _safe(chk)
    except Exception:
        return False


